test('EffectComposer advanced shader passes fail clearly with helper guidance', () => {
  class StubImage {
    set src(value) {
      this._src = value
    }

    get src() {
      return this._src
    }
  }

  function makeScene(color = 0xff0000) {
    const scene = new THREE.Scene()
    const mesh = new THREE.Mesh(
      new THREE.PlaneGeometry(2, 2),
      new THREE.MeshBasicMaterial({ color }),
    )
    scene.add(mesh)
    return { scene, mesh }
  }

  function makeCamera() {
    const camera = new THREE.PerspectiveCamera(60, 1, 0.1, 10)
    camera.position.z = 2
    camera.updateProjectionMatrix()
    return camera
  }

  const hadImage = Object.prototype.hasOwnProperty.call(globalThis, 'Image')
  const previousImage = globalThis.Image
  globalThis.Image = StubImage

  const cases = [
    [
      'UnrealBloomPass',
      () => new UnrealBloomPass(new THREE.Vector2(16, 16), 1, 0.1, 0.2),
      /UnrealBloomPass internal LuminosityHighPassShader ShaderMaterial.*not translated.*postProcessing.*custom WGSL/i,
    ],
    [
      'SSRPass',
      () => {
        const { scene } = makeScene()
        return new SSRPass({ renderer: new Renderer(), scene, camera: makeCamera(), width: 16, height: 16 })
      },
      /SSRPass internal SSRShader ShaderMaterial.*not translated.*reflections.*custom WGSL/i,
    ],
    [
      'SMAAPass',
      () => new SMAAPass(16, 16),
      /SMAAPass internal SMAAEdgesShader ShaderMaterial.*not translated.*native MSAA.*custom WGSL/i,
    ],
    [
      'OutlinePass',
      () => {
        const { scene, mesh } = makeScene()
        return new OutlinePass(new THREE.Vector2(16, 16), scene, makeCamera(), [mesh])
      },
      /OutlinePass internal prepare-mask ShaderMaterial.*not translated.*renderMode.*custom WGSL/i,
    ],
  ]

  try {
    for (const [name, createPass, pattern] of cases) {
      const renderer = new Renderer()
      const writeBuffer = new THREE.WebGLRenderTarget(16, 16)
      const readBuffer = new THREE.WebGLRenderTarget(16, 16)
      const pass = createPass()

      try {
        assert.throws(
          () => pass.render(renderer, writeBuffer, readBuffer, 0.016, false),
          pattern,
          `${name} should fail with helper-specific guidance`,
        )
      } finally {
        pass.dispose()
      }
    }
  } finally {
    if (hadImage) {
      globalThis.Image = previousImage
    } else {
      delete globalThis.Image
    }
  }
})

test('EffectComposer SSAARenderPass accumulates CopyShader samples into the active target', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 1)
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(4, 4),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  ))
  const camera = new THREE.PerspectiveCamera(60, 1, 0.1, 10)
  camera.position.z = 2

  const renderer = new Renderer()
  renderer.setSize(32, 32)
  const previousTarget = { texture: {} }
  renderer.setRenderTarget(previousTarget)

  const renderTarget = new THREE.WebGLRenderTarget(32, 32, {
    format: THREE.RGBAFormat,
    type: THREE.UnsignedByteType,
  })
  const composer = new EffectComposer(renderer, renderTarget)
  composer.renderToScreen = false
  const pass = new SSAARenderPass(scene, camera)
  pass.sampleLevel = 2
  composer.addPass(pass)

  composer.render(0)
  assert.strictEqual(renderer.getRenderTarget(), previousTarget)
  assert.equal(camera.view?.enabled, false)

  const pixels = Buffer.alloc(32 * 32 * 4)
  renderer.readRenderTargetPixels(composer.readBuffer, 0, 0, 32, 32, pixels)
  const mean = meanRegion(pixels, 32, 32, 10, 10, 22, 22)
  assert.ok(mean.r > 200, `SSAARenderPass target should accumulate red CopyShader samples (${mean.r})`)
  assert.ok(mean.r > mean.b + 80, `SSAARenderPass target should preserve red scene output (${mean.r} vs ${mean.b})`)
  assert.ok(mean.a > 220, `SSAARenderPass target should accumulate alpha (${mean.a})`)
})

