test('material stencil state masks later draws', () => {
  function renderStencilFill(stencilFunc) {
    const scene = new THREE.Scene()
    scene.background = new THREE.Color(0, 0, 0)

    const mask = new THREE.Mesh(
      new THREE.PlaneGeometry(1, 2),
      new THREE.MeshBasicMaterial({
        color: 0xff0000,
        colorWrite: false,
        depthWrite: false,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 1,
        stencilZPass: THREE.ReplaceStencilOp,
      }),
    )
    mask.position.x = -0.5
    mask.renderOrder = 0
    scene.add(mask)

    const fill = new THREE.Mesh(
      new THREE.PlaneGeometry(2, 2),
      new THREE.MeshBasicMaterial({
        color: 0x0000ff,
        stencilWrite: true,
        stencilFunc,
        stencilRef: 1,
        stencilFail: THREE.KeepStencilOp,
        stencilZFail: THREE.KeepStencilOp,
        stencilZPass: THREE.KeepStencilOp,
        stencilWriteMask: 0,
      }),
    )
    fill.renderOrder = 1
    scene.add(fill)

    const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100)
    camera.position.set(0, 0, 3)
    camera.lookAt(0, 0, 0)

    const rgba = renderRgba(scene, camera, { width: 64, height: 64 })
    return {
      left: meanRegion(rgba, 64, 64, 16, 24, 28, 40),
      right: meanRegion(rgba, 64, 64, 42, 24, 54, 40),
    }
  }

  const cases = [
    ['NeverStencilFunc', THREE.NeverStencilFunc, false, false],
    ['LessStencilFunc', THREE.LessStencilFunc, false, false],
    ['EqualStencilFunc', THREE.EqualStencilFunc, true, false],
    ['LessEqualStencilFunc', THREE.LessEqualStencilFunc, true, false],
    ['GreaterStencilFunc', THREE.GreaterStencilFunc, false, true],
    ['NotEqualStencilFunc', THREE.NotEqualStencilFunc, false, true],
    ['GreaterEqualStencilFunc', THREE.GreaterEqualStencilFunc, true, true],
    ['AlwaysStencilFunc', THREE.AlwaysStencilFunc, true, true],
  ]
  for (const [label, stencilFunc, expectLeft, expectRight] of cases) {
    const { left, right } = renderStencilFill(stencilFunc)
    if (expectLeft) {
      assert.ok(left.b > 150, `${label} should render inside the stencil mask (${left.b})`)
    } else {
      assert.ok(left.b < 10, `${label} should reject inside the stencil mask (${left.b})`)
    }
    if (expectRight) {
      assert.ok(right.b > 150, `${label} should render outside the stencil mask (${right.b})`)
    } else {
      assert.ok(right.b < 10, `${label} should reject outside the stencil mask (${right.b})`)
    }
  }
})

test('material stencil z-pass operations update stencil values', () => {
  function renderStencilOperation(stencilZPass, expectedRef) {
    const scene = new THREE.Scene()
    scene.background = new THREE.Color(0, 0, 0)

    const geometry = new THREE.PlaneGeometry(1, 2)
    const preload = new THREE.Mesh(
      geometry,
      new THREE.MeshBasicMaterial({
        color: 0xff0000,
        colorWrite: false,
        depthWrite: false,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 1,
        stencilZPass: THREE.ReplaceStencilOp,
      }),
    )
    preload.position.x = -0.5
    preload.renderOrder = 0
    scene.add(preload)

    const operation = new THREE.Mesh(
      geometry,
      new THREE.MeshBasicMaterial({
        color: 0x00ff00,
        colorWrite: false,
        depthWrite: false,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 2,
        stencilZPass,
      }),
    )
    operation.position.x = -0.5
    operation.renderOrder = 1
    scene.add(operation)

    const fill = new THREE.Mesh(
      new THREE.PlaneGeometry(2, 2),
      new THREE.MeshBasicMaterial({
        color: 0x0000ff,
        stencilWrite: true,
        stencilFunc: THREE.EqualStencilFunc,
        stencilRef: expectedRef,
        stencilFail: THREE.KeepStencilOp,
        stencilZFail: THREE.KeepStencilOp,
        stencilZPass: THREE.KeepStencilOp,
        stencilWriteMask: 0,
      }),
    )
    fill.renderOrder = 2
    scene.add(fill)

    const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100)
    camera.position.set(0, 0, 3)
    camera.lookAt(0, 0, 0)

    const rgba = renderRgba(scene, camera, { width: 64, height: 64 })
    return {
      left: meanRegion(rgba, 64, 64, 16, 24, 28, 40),
      right: meanRegion(rgba, 64, 64, 42, 24, 54, 40),
    }
  }

  const cases = [
    ['ZeroStencilOp', THREE.ZeroStencilOp, 0],
    ['KeepStencilOp', THREE.KeepStencilOp, 1],
    ['ReplaceStencilOp', THREE.ReplaceStencilOp, 2],
    ['IncrementStencilOp', THREE.IncrementStencilOp, 2],
    ['DecrementStencilOp', THREE.DecrementStencilOp, 0],
    ['IncrementWrapStencilOp', THREE.IncrementWrapStencilOp, 2],
    ['DecrementWrapStencilOp', THREE.DecrementWrapStencilOp, 0],
    ['InvertStencilOp', THREE.InvertStencilOp, 254],
  ]
  for (const [label, stencilZPass, expectedRef] of cases) {
    const { left } = renderStencilOperation(stencilZPass, expectedRef)
    assert.ok(left.b > 150, `${label} should update the left stencil value to ${expectedRef} (${left.b})`)
  }
})

test('material stencil masks limit writes and comparisons', () => {
  function renderWriteMask(stencilWriteMask) {
    const scene = new THREE.Scene()
    scene.background = new THREE.Color(0, 0, 0)

    const preload = new THREE.Mesh(
      new THREE.PlaneGeometry(1, 2),
      new THREE.MeshBasicMaterial({
        color: 0xff0000,
        colorWrite: false,
        depthWrite: false,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 1,
        stencilZPass: THREE.ReplaceStencilOp,
      }),
    )
    preload.position.x = -0.5
    preload.renderOrder = 0
    scene.add(preload)

    const operation = new THREE.Mesh(
      new THREE.PlaneGeometry(1, 2),
      new THREE.MeshBasicMaterial({
        color: 0x00ff00,
        colorWrite: false,
        depthWrite: false,
        stencilWrite: true,
        stencilWriteMask,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 2,
        stencilZPass: THREE.ReplaceStencilOp,
      }),
    )
    operation.position.x = -0.5
    operation.renderOrder = 1
    scene.add(operation)

    const fill = new THREE.Mesh(
      new THREE.PlaneGeometry(2, 2),
      new THREE.MeshBasicMaterial({
        color: 0x0000ff,
        stencilWrite: true,
        stencilWriteMask: 0,
        stencilFunc: THREE.EqualStencilFunc,
        stencilRef: 2,
        stencilZPass: THREE.KeepStencilOp,
      }),
    )
    fill.renderOrder = 2
    scene.add(fill)

    const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100)
    camera.position.set(0, 0, 3)
    camera.lookAt(0, 0, 0)
    return meanRegion(renderRgba(scene, camera, { width: 64, height: 64 }), 64, 64, 16, 24, 28, 40)
  }

  function renderFuncMask(stencilFuncMask) {
    const scene = new THREE.Scene()
    scene.background = new THREE.Color(0, 0, 0)

    const mask = new THREE.Mesh(
      new THREE.PlaneGeometry(1, 2),
      new THREE.MeshBasicMaterial({
        color: 0xff0000,
        colorWrite: false,
        depthWrite: false,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 2,
        stencilZPass: THREE.ReplaceStencilOp,
      }),
    )
    mask.position.x = -0.5
    mask.renderOrder = 0
    scene.add(mask)

    const fill = new THREE.Mesh(
      new THREE.PlaneGeometry(2, 2),
      new THREE.MeshBasicMaterial({
        color: 0x0000ff,
        stencilWrite: true,
        stencilWriteMask: 0,
        stencilFunc: THREE.EqualStencilFunc,
        stencilRef: 3,
        stencilFuncMask,
        stencilZPass: THREE.KeepStencilOp,
      }),
    )
    fill.renderOrder = 1
    scene.add(fill)

    const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100)
    camera.position.set(0, 0, 3)
    camera.lookAt(0, 0, 0)
    return meanRegion(renderRgba(scene, camera, { width: 64, height: 64 }), 64, 64, 16, 24, 28, 40)
  }

  const writeAllowed = renderWriteMask(0xff)
  const writeBlocked = renderWriteMask(0)
  assert.ok(writeAllowed.b > 150, `full stencilWriteMask should allow replacement writes (${writeAllowed.b})`)
  assert.ok(writeBlocked.b < 10, `zero stencilWriteMask should preserve the previous stencil value (${writeBlocked.b})`)

  const unmaskedComparison = renderFuncMask(0xff)
  const maskedComparison = renderFuncMask(0x02)
  assert.ok(unmaskedComparison.b < 10, `full stencilFuncMask should reject distinct stencil refs (${unmaskedComparison.b})`)
  assert.ok(maskedComparison.b > 150, `masked stencilFuncMask should compare only selected bits (${maskedComparison.b})`)
})

function assertMaterialRenderStateFails(material, pattern) {
  const scene = new THREE.Scene()
  scene.add(new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material))

  assert.throws(
    () => renderRgba(scene, makeCamera(), { width: 32, height: 32 }),
    pattern,
  )
}

