test('renderToTarget depthTexture preserves alphaHash cutouts', () => {
  function renderAlphaHashDepth(alphaHash) {
    const scene = new THREE.Scene()
    scene.background = new THREE.Color(0, 0, 0)
    scene.add(new THREE.Mesh(
      new THREE.PlaneGeometry(2, 2),
      new THREE.MeshBasicMaterial({
        alphaHash,
        color: 0xffffff,
        opacity: alphaHash ? 0.35 : 1,
      }),
    ))

    const camera = new THREE.OrthographicCamera(-2, 2, 2, -2, 0.1, 10)
    camera.position.set(0, 0, 5)
    camera.lookAt(0, 0, 0)

    const depthTexture = {}
    renderToTarget(scene, camera, { texture: {}, depthTexture }, { width: 64, height: 64 })
    return depthTexture.image.data
  }

  const opaque = renderAlphaHashDepth(false)
  const hashed = renderAlphaHashDepth(true)
  const depthPixel = (r) => r > 2
  const opaquePixels = countRegionPixels(opaque, 64, 64, 20, 20, 44, 44, depthPixel)
  const hashedPixels = countRegionPixels(hashed, 64, 64, 20, 20, 44, 44, depthPixel)

  assert.ok(opaquePixels > 520, `opaque target depth should fill the sampled region (${opaquePixels})`)
  assert.ok(hashedPixels > 40, `alphaHash target depth should retain some depth pixels (${hashedPixels})`)
  assert.ok(hashedPixels < opaquePixels - 120, `alphaHash target depth should discard depth pixels (${hashedPixels} vs ${opaquePixels})`)
})

test('renderToTarget depthTexture honors transparent default depthWrite', () => {
  function renderTransparentDepth(depthWrite) {
    const scene = new THREE.Scene()
    scene.background = new THREE.Color(0, 0, 0)
    const material = new THREE.MeshBasicMaterial({
      color: 0xff0000,
      opacity: 0.5,
      transparent: true,
    })
    if (depthWrite !== undefined) material.depthWrite = depthWrite
    scene.add(new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material))

    const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100)
    camera.position.set(0, 0, 3)
    camera.lookAt(0, 0, 0)

    const depthTexture = {}
    renderToTarget(scene, camera, { texture: {}, depthTexture }, { width: 64, height: 64 })
    return meanRegion(depthTexture.image.data, 64, 64, 24, 24, 40, 40)
  }

  const defaultDepth = renderTransparentDepth(undefined)
  const disabledDepth = renderTransparentDepth(false)

  assert.ok(defaultDepth.r > disabledDepth.r + 0.5, `transparent default depthWrite should populate target depth (${defaultDepth.r} vs ${disabledDepth.r})`)
  assert.ok(disabledDepth.r < 0.5, `transparent depthWrite=false should leave target depth clear (${disabledDepth.r})`)
})

test('renderToTarget color textures honor typed readback requests', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(2, 2),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  ))

  const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100)
  camera.position.set(0, 0, 3)
  camera.lookAt(0, 0, 0)

  const center = ((32 * 64) + 32) * 4
  const options = { width: 64, height: 64, outputColorSpace: THREE.LinearSRGBColorSpace }

  const redTarget = { texture: { format: THREE.RedFormat } }
  renderToTarget(scene, camera, redTarget, options)
  const redData = redTarget.texture.image.data
  const redCenter = (32 * 64) + 32
  assert.ok(redData instanceof Uint8Array, 'RedFormat color target should receive Uint8Array data')
  assert.equal(redData.length, 64 * 64, 'RedFormat color target should receive one channel per pixel')
  assert.ok(redData[redCenter] > 128, `RedFormat red channel should keep the source red (${redData[redCenter]})`)

  const luminanceTarget = { texture: { format: THREE.LuminanceFormat } }
  renderToTarget(scene, camera, luminanceTarget, options)
  const luminanceData = luminanceTarget.texture.image.data
  assert.ok(luminanceData instanceof Uint8Array, 'LuminanceFormat color target should receive Uint8Array data')
  assert.equal(luminanceData.length, 64 * 64, 'LuminanceFormat color target should receive one channel per pixel')
  assert.ok(luminanceData[redCenter] > 128, `LuminanceFormat luminance should keep the source red channel (${luminanceData[redCenter]})`)

  const alphaScene = new THREE.Scene()
  alphaScene.background = new THREE.Color(0, 0, 1)
  alphaScene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(2, 2),
    new THREE.MeshBasicMaterial({ color: 0x0000ff }),
  ))
  const alphaTarget = { texture: { format: THREE.AlphaFormat } }
  renderToTarget(alphaScene, camera, alphaTarget, options)
  const alphaData = alphaTarget.texture.image.data
  assert.ok(alphaData instanceof Uint8Array, 'AlphaFormat color target should receive Uint8Array data')
  assert.equal(alphaData.length, 64 * 64, 'AlphaFormat color target should receive one channel per pixel')
  assert.ok(alphaData[redCenter] > 250, `AlphaFormat should extract opaque alpha instead of red (${alphaData[redCenter]})`)

  const luminanceAlphaScene = new THREE.Scene()
  luminanceAlphaScene.background = { r: 1, g: 0, b: 0, a: 0.5 }
  const luminanceAlphaTarget = { texture: { format: THREE.LuminanceAlphaFormat, type: THREE.FloatType } }
  renderToTarget(luminanceAlphaScene, camera, luminanceAlphaTarget, options)
  const luminanceAlphaData = luminanceAlphaTarget.texture.image.data
  const luminanceAlphaCenter = redCenter * 2
  assert.ok(luminanceAlphaData instanceof Float32Array, 'LuminanceAlphaFormat FloatType color target should receive Float32Array data')
  assert.equal(luminanceAlphaData.length, 64 * 64 * 2, 'LuminanceAlphaFormat color target should receive two channels per pixel')
  assert.ok(luminanceAlphaData[luminanceAlphaCenter] > 0.99, `LuminanceAlphaFormat luminance should keep red clear color (${luminanceAlphaData[luminanceAlphaCenter]})`)
  assert.ok(Math.abs(luminanceAlphaData[luminanceAlphaCenter + 1] - 0.5) < 0.01, `LuminanceAlphaFormat alpha should keep clear alpha (${luminanceAlphaData[luminanceAlphaCenter + 1]})`)

  const floatTarget = { texture: { type: THREE.FloatType } }
  renderToTarget(scene, camera, floatTarget, options)
  const floatData = floatTarget.texture.image.data
  assert.ok(floatData instanceof Float32Array, 'FloatType color target should receive Float32Array data')
  assert.ok(Buffer.isBuffer(floatTarget.data), 'target.data should remain raw RGBA8 for compatibility')
  assert.ok(floatData[center] > 0.5, `FloatType red channel should be normalized (${floatData[center]})`)
  assert.ok(floatData[center + 1] < 0.05, `FloatType green channel should stay near zero (${floatData[center + 1]})`)
  assert.ok(floatData[center + 3] > 0.99, `FloatType alpha channel should stay opaque (${floatData[center + 3]})`)

  const byteTarget = { texture: { type: THREE.ByteType } }
  renderToTarget(scene, camera, byteTarget, options)
  const byteData = byteTarget.texture.image.data
  assert.ok(byteData instanceof Int8Array, 'ByteType color target should receive Int8Array data')
  assert.ok(byteData[center] > 63, `ByteType red channel should be normalized (${byteData[center]})`)
  assert.ok(byteData[center + 1] < 8, `ByteType green channel should stay near zero (${byteData[center + 1]})`)
  assert.ok(byteData[center + 3] > 120, `ByteType alpha channel should stay opaque (${byteData[center + 3]})`)

  const rgFloatTarget = { texture: { format: THREE.RGFormat, type: THREE.FloatType } }
  renderToTarget(scene, camera, rgFloatTarget, options)
  const rgFloatData = rgFloatTarget.texture.image.data
  const rgCenter = ((32 * 64) + 32) * 2
  assert.ok(rgFloatData instanceof Float32Array, 'RGFormat FloatType color target should receive Float32Array data')
  assert.equal(rgFloatData.length, 64 * 64 * 2, 'RGFormat color target should receive two channels per pixel')
  assert.ok(rgFloatData[rgCenter] > 0.5, `RGFormat FloatType red channel should be normalized (${rgFloatData[rgCenter]})`)
  assert.ok(rgFloatData[rgCenter + 1] < 0.05, `RGFormat FloatType green channel should stay near zero (${rgFloatData[rgCenter + 1]})`)

  for (const [label, format, channels] of [
    ['RedIntegerFormat', THREE.RedIntegerFormat, 1],
    ['RGIntegerFormat', THREE.RGIntegerFormat, 2],
    ['RGBIntegerFormat', THREE.RGBIntegerFormat, 3],
    ['RGBAIntegerFormat', THREE.RGBAIntegerFormat, 4],
  ]) {
    const target = { texture: { format, type: THREE.UnsignedShortType } }
    renderToTarget(scene, camera, target, options)
    const data = target.texture.image.data
    const pixel = redCenter * channels
    assert.ok(data instanceof Uint16Array, `${label} color target should receive Uint16Array data`)
    assert.equal(data.length, 64 * 64 * channels, `${label} color target should receive ${channels} channel(s) per pixel`)
    assert.ok(data[pixel] > 0x8000, `${label} red channel should be normalized (${data[pixel]})`)
    if (channels > 1) assert.ok(data[pixel + 1] < 0x1000, `${label} green channel should stay near zero (${data[pixel + 1]})`)
    if (channels > 2) assert.ok(data[pixel + 2] < 0x1000, `${label} blue channel should stay near zero (${data[pixel + 2]})`)
    if (channels > 3) assert.ok(data[pixel + 3] > 0xff00, `${label} alpha channel should stay opaque (${data[pixel + 3]})`)
  }

  const ushortTarget = { texture: { type: THREE.UnsignedShortType } }
  renderToTarget(scene, camera, ushortTarget, options)
  const ushortData = ushortTarget.texture.image.data
  assert.ok(ushortData instanceof Uint16Array, 'UnsignedShortType color target should receive Uint16Array data')
  assert.ok(ushortData[center] > 0x8000, `UnsignedShortType red channel should be normalized (${ushortData[center]})`)
  assert.ok(ushortData[center + 1] < 0x1000, `UnsignedShortType green channel should stay near zero (${ushortData[center + 1]})`)
  assert.ok(ushortData[center + 3] > 0xff00, `UnsignedShortType alpha channel should stay opaque (${ushortData[center + 3]})`)

  const shortTarget = { texture: { type: THREE.ShortType } }
  renderToTarget(scene, camera, shortTarget, options)
  const shortData = shortTarget.texture.image.data
  assert.ok(shortData instanceof Int16Array, 'ShortType color target should receive Int16Array data')
  assert.ok(shortData[center] > 0x4000, `ShortType red channel should be normalized (${shortData[center]})`)
  assert.ok(shortData[center + 1] < 0x1000, `ShortType green channel should stay near zero (${shortData[center + 1]})`)
  assert.ok(shortData[center + 3] > 0x7f00, `ShortType alpha channel should stay opaque (${shortData[center + 3]})`)

  const rgbUshortTarget = { texture: { format: THREE.RGBFormat, type: THREE.UnsignedShortType } }
  renderToTarget(scene, camera, rgbUshortTarget, options)
  const rgbUshortData = rgbUshortTarget.texture.image.data
  const rgbCenter = ((32 * 64) + 32) * 3
  assert.ok(rgbUshortData instanceof Uint16Array, 'RGBFormat UnsignedShortType color target should receive Uint16Array data')
  assert.equal(rgbUshortData.length, 64 * 64 * 3, 'RGBFormat color target should receive three channels per pixel')
  assert.ok(rgbUshortData[rgbCenter] > 0x8000, `RGBFormat red channel should be normalized (${rgbUshortData[rgbCenter]})`)
  assert.ok(rgbUshortData[rgbCenter + 1] < 0x1000, `RGBFormat green channel should stay near zero (${rgbUshortData[rgbCenter + 1]})`)
  assert.ok(rgbUshortData[rgbCenter + 2] < 0x1000, `RGBFormat blue channel should stay near zero (${rgbUshortData[rgbCenter + 2]})`)

  const packed4444Target = { texture: { type: THREE.UnsignedShort4444Type } }
  renderToTarget(scene, camera, packed4444Target, options)
  const packed4444Data = packed4444Target.texture.image.data
  const packed4444 = packed4444Data[redCenter]
  assert.ok(packed4444Data instanceof Uint16Array, 'UnsignedShort4444Type color target should receive Uint16Array data')
  assert.ok(((packed4444 >> 12) & 0xf) > 7, `UnsignedShort4444Type red channel should be packed (${packed4444.toString(16)})`)
  assert.ok(((packed4444 >> 8) & 0xf) < 2, `UnsignedShort4444Type green channel should stay near zero (${packed4444.toString(16)})`)
  assert.ok(((packed4444 >> 4) & 0xf) < 2, `UnsignedShort4444Type blue channel should stay near zero (${packed4444.toString(16)})`)
  assert.equal(packed4444 & 0xf, 0xf, `UnsignedShort4444Type alpha channel should stay opaque (${packed4444.toString(16)})`)

  const packed5551Target = { texture: { type: THREE.UnsignedShort5551Type } }
  renderToTarget(scene, camera, packed5551Target, options)
  const packed5551Data = packed5551Target.texture.image.data
  const packed5551 = packed5551Data[redCenter]
  assert.ok(packed5551Data instanceof Uint16Array, 'UnsignedShort5551Type color target should receive Uint16Array data')
  assert.ok(((packed5551 >> 11) & 0x1f) > 15, `UnsignedShort5551Type red channel should be packed (${packed5551.toString(16)})`)
  assert.ok(((packed5551 >> 6) & 0x1f) < 2, `UnsignedShort5551Type green channel should stay near zero (${packed5551.toString(16)})`)
  assert.ok(((packed5551 >> 1) & 0x1f) < 2, `UnsignedShort5551Type blue channel should stay near zero (${packed5551.toString(16)})`)
  assert.equal(packed5551 & 0x1, 1, `UnsignedShort5551Type alpha channel should stay opaque (${packed5551.toString(16)})`)

  const rgb9e5Target = { texture: { type: THREE.UnsignedInt5999Type } }
  renderToTarget(scene, camera, rgb9e5Target, options)
  const rgb9e5Data = rgb9e5Target.texture.image.data
  const rgb9e5 = rgb9e5Data[redCenter]
  const rgb9e5Scale = 2 ** (((rgb9e5 >>> 27) & 0x1f) - 24)
  const rgb9e5Red = (rgb9e5 & 0x1ff) * rgb9e5Scale
  const rgb9e5Green = ((rgb9e5 >>> 9) & 0x1ff) * rgb9e5Scale
  const rgb9e5Blue = ((rgb9e5 >>> 18) & 0x1ff) * rgb9e5Scale
  assert.ok(rgb9e5Data instanceof Uint32Array, 'UnsignedInt5999Type color target should receive Uint32Array data')
  assert.ok(rgb9e5Red > 0.5, `UnsignedInt5999Type red channel should be packed (${rgb9e5Red})`)
  assert.ok(rgb9e5Green < 0.05, `UnsignedInt5999Type green channel should stay near zero (${rgb9e5Green})`)
  assert.ok(rgb9e5Blue < 0.05, `UnsignedInt5999Type blue channel should stay near zero (${rgb9e5Blue})`)

  const r11Target = { texture: { type: UnsignedInt101111Type } }
  renderToTarget(scene, camera, r11Target, options)
  const r11Data = r11Target.texture.image.data
  const r11 = r11Data[redCenter]
  const r11Red = unsignedFloatToNumber(r11 & 0x7ff, 6)
  const r11Green = unsignedFloatToNumber((r11 >>> 11) & 0x7ff, 6)
  const r11Blue = unsignedFloatToNumber((r11 >>> 22) & 0x3ff, 5)
  assert.ok(r11Data instanceof Uint32Array, 'UnsignedInt101111Type color target should receive Uint32Array data')
  assert.ok(r11Red > 0.5, `UnsignedInt101111Type red channel should be packed (${r11Red})`)
  assert.ok(r11Green < 0.05, `UnsignedInt101111Type green channel should stay near zero (${r11Green})`)
  assert.ok(r11Blue < 0.05, `UnsignedInt101111Type blue channel should stay near zero (${r11Blue})`)

  const uintTarget = { texture: { type: THREE.UnsignedIntType } }
  renderToTarget(scene, camera, uintTarget, options)
  const uintData = uintTarget.texture.image.data
  assert.ok(uintData instanceof Uint32Array, 'UnsignedIntType color target should receive Uint32Array data')
  assert.ok(uintData[center] > 0x80000000, `UnsignedIntType red channel should be normalized (${uintData[center]})`)
  assert.ok(uintData[center + 1] < 0x10000000, `UnsignedIntType green channel should stay near zero (${uintData[center + 1]})`)
  assert.ok(uintData[center + 3] > 0xff000000, `UnsignedIntType alpha channel should stay opaque (${uintData[center + 3]})`)

  const intTarget = { texture: { type: THREE.IntType } }
  renderToTarget(scene, camera, intTarget, options)
  const intData = intTarget.texture.image.data
  assert.ok(intData instanceof Int32Array, 'IntType color target should receive Int32Array data')
  assert.ok(intData[center] > 0x40000000, `IntType red channel should be normalized (${intData[center]})`)
  assert.ok(intData[center + 1] < 0x10000000, `IntType green channel should stay near zero (${intData[center + 1]})`)
  assert.ok(intData[center + 3] > 0x7f000000, `IntType alpha channel should stay opaque (${intData[center + 3]})`)

  const halfTarget = { texture: { type: THREE.HalfFloatType } }
  renderToTarget(scene, camera, halfTarget, options)
  const halfData = halfTarget.texture.image.data
  assert.ok(halfData instanceof Uint16Array, 'HalfFloatType color target should receive Uint16Array half-float data')
  const halfRed = halfFloatToNumber(halfData[center])
  const halfGreen = halfFloatToNumber(halfData[center + 1])
  const halfAlpha = halfFloatToNumber(halfData[center + 3])
  assert.ok(halfRed > 0.5, `HalfFloatType red channel should be normalized (${halfRed})`)
  assert.ok(halfGreen < 0.05, `HalfFloatType green channel should stay near zero (${halfGreen})`)
  assert.ok(halfAlpha > 0.99, `HalfFloatType alpha channel should stay opaque (${halfAlpha})`)
})

test('Three.js exporters read targets through the WebGLRenderer marker path', async () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(2, 2),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  ))

  const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100)
  camera.position.set(0, 0, 3)
  camera.lookAt(0, 0, 0)

  const renderer = new Renderer()
  const renderOptions = { outputColorSpace: THREE.LinearSRGBColorSpace }

  const exrTarget = new THREE.WebGLRenderTarget(16, 16, {
    format: THREE.RGBAFormat,
    type: THREE.HalfFloatType,
  })
  exrTarget.texture.colorSpace = THREE.LinearSRGBColorSpace
  renderToTarget(scene, camera, exrTarget, renderOptions)
  assert.ok(exrTarget.texture.image.data instanceof Uint16Array, 'EXR target should receive half-float render data')

  const exr = await new EXRExporter().parse(renderer, exrTarget, {
    compression: NO_COMPRESSION,
    type: THREE.HalfFloatType,
  })
  assert.ok(exr instanceof Uint8Array, 'EXRExporter should return Uint8Array data')
  assert.ok(exr.length > 16 * 16 * 8, `EXR output should include header and pixel data (${exr.length})`)
  assert.deepEqual(
    Array.from(exr.subarray(0, 4)),
    [0x76, 0x2f, 0x31, 0x01],
    'EXRExporter output should start with the OpenEXR magic number',
  )

  const ktxTarget = new THREE.WebGLRenderTarget(16, 16, {
    format: THREE.RGBAFormat,
    type: THREE.UnsignedByteType,
  })
  ktxTarget.texture.colorSpace = THREE.SRGBColorSpace
  renderToTarget(scene, camera, ktxTarget, renderOptions)
  assert.ok(ktxTarget.texture.image.data instanceof Uint8Array, 'KTX2 target should receive byte render data')

  const ktx = await new KTX2Exporter().parse(renderer, ktxTarget)
  assert.ok(ktx instanceof Uint8Array, 'KTX2Exporter should return Uint8Array data')
  assert.ok(ktx.length > 16 * 16 * 4, `KTX2 output should include header and pixel data (${ktx.length})`)
  assert.deepEqual(
    Array.from(ktx.subarray(0, 12)),
    [0xab, 0x4b, 0x54, 0x58, 0x20, 0x32, 0x30, 0xbb, 0x0d, 0x0a, 0x1a, 0x0a],
    'KTX2Exporter output should start with the KTX2 identifier',
  )
})

test('single-attachment target array paths honor typed color readback requests', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(2, 2),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  ))

  const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 100)
  camera.position.set(0, 0, 3)
  camera.lookAt(0, 0, 0)

  const options = { width: 32, height: 32, outputColorSpace: THREE.LinearSRGBColorSpace }
  const center = ((16 * 32) + 16) * 2
  const cases = [
    ['target.texture array', { texture: [{ format: THREE.RGFormat, type: THREE.FloatType }] }, (target) => target.texture[0]],
    ['target.textures array', { textures: [{ format: THREE.RGFormat, type: THREE.FloatType }] }, (target) => target.textures[0]],
    ['single-attachment MRT target', { isWebGLMultipleRenderTargets: true, textures: [{ format: THREE.RGFormat, type: THREE.FloatType }] }, (target) => target.textures[0]],
  ]

  for (const [label, target, colorTexture] of cases) {
    renderToTarget(scene, camera, target, options)
    const data = colorTexture(target).image.data
    assert.ok(Buffer.isBuffer(target.data), `${label} top-level target.data should remain RGBA8`)
    assert.ok(data instanceof Float32Array, `${label} should receive Float32Array data`)
    assert.equal(data.length, 32 * 32 * 2, `${label} should receive two channels per pixel`)
    assert.equal(colorTexture(target).source.data.data, data, `${label} source should reference typed data`)
    assert.ok(data[center] > 0.5, `${label} red channel should be normalized (${data[center]})`)
    assert.ok(data[center + 1] < 0.05, `${label} green channel should stay near zero (${data[center + 1]})`)
  }

  const optionsTarget = { textures: [{ format: THREE.RGFormat, type: THREE.FloatType }] }
  const returned = renderRgba(scene, camera, { ...options, target: optionsTarget })
  const data = optionsTarget.textures[0].image.data
  assert.equal(optionsTarget.data, returned)
  assert.ok(data instanceof Float32Array, 'options.target target.textures[0] should receive Float32Array data')
  assert.equal(data.length, 32 * 32 * 2)
  assert.ok(data[center] > 0.5, `options.target red channel should be normalized (${data[center]})`)
  assert.ok(data[center + 1] < 0.05, `options.target green channel should stay near zero (${data[center + 1]})`)
})

test('MRT-shaped targets can request auxiliary render-mode attachments', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(1.2, 1.2),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  )
  mesh.rotation.y = Math.PI * 0.2
  scene.add(mesh)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 3)
  camera.lookAt(0, 0, 0)

  const target = {
    isWebGLMultipleRenderTargets: true,
    textures: [
      {},
      { format: THREE.RGFormat, type: THREE.FloatType, userData: { headlessThreeRenderer: { renderMode: 'color' } } },
      { userData: { headlessThreeRenderer: { renderMode: 'mask' } } },
      { userData: { headlessThreeRenderer: { renderMode: 'object-id' } } },
      { userData: { headlessThreeRenderer: { renderMode: 'normal' } } },
      { userData: { headlessThreeRenderer: { renderMode: 'depth' } } },
    ],
  }
  renderToTarget(scene, camera, target, {
    width: 64,
    height: 64,
    outputColorSpace: THREE.LinearSRGBColorSpace,
  })

  assert.equal(target.textures[0].image.data, target.data)
  const colorCenter = meanRegion(target.data, 64, 64, 28, 28, 36, 36)
  assert.ok(colorCenter.r > 180 && colorCenter.g < 20 && colorCenter.b < 20, `primary color attachment should stay red (${colorCenter.r}, ${colorCenter.g}, ${colorCenter.b})`)

  const colorCopyData = target.textures[1].image.data
  const colorCopyCenter = ((32 * 64) + 32) * 2
  assert.ok(colorCopyData instanceof Float32Array, 'secondary color attachment should honor FloatType RG readback')
  assert.equal(colorCopyData.length, 64 * 64 * 2)
  assert.equal(target.textures[1].source.data.data, colorCopyData)
  assert.ok(colorCopyData[colorCopyCenter] > 0.7, `secondary color attachment red channel should be normalized (${colorCopyData[colorCopyCenter]})`)
  assert.ok(colorCopyData[colorCopyCenter + 1] < 0.05, `secondary color attachment green channel should stay near zero (${colorCopyData[colorCopyCenter + 1]})`)

  const maskCenter = meanRegion(target.textures[2].image.data, 64, 64, 28, 28, 36, 36)
  const maskCorner = meanRegion(target.textures[2].image.data, 64, 64, 0, 0, 8, 8)
  assert.ok(maskCenter.r > 250 && maskCenter.g > 250 && maskCenter.b > 250, `mask attachment center should be white (${maskCenter.r}, ${maskCenter.g}, ${maskCenter.b})`)
  assert.ok(maskCorner.r < 2 && maskCorner.g < 2 && maskCorner.b < 2, `mask attachment background should be black (${maskCorner.r}, ${maskCorner.g}, ${maskCorner.b})`)

  const objectIdCenter = meanRegion(target.textures[3].image.data, 64, 64, 28, 28, 36, 36)
  const encoded = mesh.id + 1
  assertRgbClose(objectIdCenter, objectIdBytes(encoded), 'auxiliary object-id attachment')
  assert.equal(target.objectIdMap[String(encoded)].id, mesh.id)

  const normalCenter = meanRegion(target.textures[4].image.data, 64, 64, 28, 28, 36, 36)
  assert.ok(normalCenter.r > 120 && normalCenter.b > 200, `normal attachment should encode the tilted view normal (${normalCenter.r}, ${normalCenter.g}, ${normalCenter.b})`)

  const depthCenter = meanRegion(target.textures[5].image.data, 64, 64, 28, 28, 36, 36)
  const depthCorner = meanRegion(target.textures[5].image.data, 64, 64, 0, 0, 8, 8)
  assert.ok(depthCenter.r > depthCorner.r + 20, `depth attachment should encode nearer mesh depth over background (${depthCenter.r} vs ${depthCorner.r})`)
  assert.ok(depthCenter.r > 150, `depth attachment center should be bright for the near mesh (${depthCenter.r})`)

  const countedTarget = new THREE.WebGLRenderTarget(64, 64, { count: 2 })
  countedTarget.textures[1].userData.headlessThreeRenderer = { renderMode: 'mask' }
  renderToTarget(scene, camera, countedTarget, {
    outputColorSpace: THREE.LinearSRGBColorSpace,
  })
  assert.strictEqual(countedTarget.texture, countedTarget.textures[0])
  const countedMaskCenter = meanRegion(countedTarget.textures[1].image.data, 64, 64, 28, 28, 36, 36)
  assert.ok(countedMaskCenter.r > 250, `WebGLRenderTarget count auxiliary mask should render (${countedMaskCenter.r})`)

  const optionsTarget = {
    textures: [
      {},
      { userData: { headlessThreeRenderer: { renderMode: 'mask' } } },
    ],
  }
  const returned = renderRgba(scene, camera, {
    width: 64,
    height: 64,
    target: optionsTarget,
    outputColorSpace: THREE.LinearSRGBColorSpace,
  })
  assert.equal(returned, optionsTarget.data)
  const optionsMaskCenter = meanRegion(optionsTarget.textures[1].image.data, 64, 64, 28, 28, 36, 36)
  assert.ok(optionsMaskCenter.r > 250, `options.target auxiliary mask should render (${optionsMaskCenter.r})`)

  const rendererTarget = {
    textures: [
      {},
      { userData: { headlessThreeRenderer: { renderMode: 'normal' } } },
    ],
  }
  const renderer = new Renderer()
  renderer.setRenderTarget(rendererTarget)
  const rendererReturned = renderer.render(scene, camera, {
    width: 64,
    height: 64,
    outputColorSpace: THREE.LinearSRGBColorSpace,
  })
  assert.equal(rendererReturned, rendererTarget.data)
  const rendererNormalCenter = meanRegion(rendererTarget.textures[1].image.data, 64, 64, 28, 28, 36, 36)
  assert.ok(rendererNormalCenter.r > 120 && rendererNormalCenter.b > 200, `Renderer.setRenderTarget auxiliary normal should render (${rendererNormalCenter.r}, ${rendererNormalCenter.g}, ${rendererNormalCenter.b})`)
})

test('MSAA sampleCount 4 resolves antialiased color output and render targets', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute([
    -1, -1, 0,
    1, -1, 0,
    -1, 1, 0,
  ], 3))
  geometry.setIndex([0, 1, 2])
  scene.add(new THREE.Mesh(geometry, new THREE.MeshBasicMaterial({ color: 0xffffff })))

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 3)
  camera.lookAt(0, 0, 0)

  const single = renderRgba(scene, camera, {
    width: 64,
    height: 64,
    outputColorSpace: THREE.LinearSRGBColorSpace,
  })
  const msaa = renderRgba(scene, camera, {
    width: 64,
    height: 64,
    sampleCount: 4,
    outputColorSpace: THREE.LinearSRGBColorSpace,
  })
  const msaaSamplesAlias = renderRgba(scene, camera, {
    width: 64,
    height: 64,
    samples: 4,
    outputColorSpace: THREE.LinearSRGBColorSpace,
  })

  function intermediateCoverage(rgba) {
    return countRegionPixels(rgba, 64, 64, 0, 0, 64, 64, (r, g, b) => {
      return r > 20 && r < 180 && Math.abs(r - g) < 3 && Math.abs(r - b) < 3
    })
  }

  const singleCoverage = intermediateCoverage(single)
  const msaaCoverage = intermediateCoverage(msaa)
  const msaaAliasCoverage = intermediateCoverage(msaaSamplesAlias)
  assert.ok(msaaCoverage > singleCoverage + 20, `4x MSAA should add resolved edge coverage (${msaaCoverage} vs ${singleCoverage})`)
  assert.ok(msaaAliasCoverage > singleCoverage + 20, `4x MSAA samples alias should add resolved edge coverage (${msaaAliasCoverage} vs ${singleCoverage})`)

  for (const [label, target] of [
    ['target.samples', { texture: {}, samples: 4 }],
    ['target.sampleCount', { texture: {}, sampleCount: 4 }],
  ]) {
    renderToTarget(scene, camera, target, {
      width: 64,
      height: 64,
      outputColorSpace: THREE.LinearSRGBColorSpace,
    })
    assert.equal(target.data.length, 64 * 64 * 4, `${label} target should receive RGBA8 data`)
    assert.equal(target.texture.image.data, target.data, `${label} texture should reference target data`)
    const targetCoverage = intermediateCoverage(target.data)
    assert.ok(
      targetCoverage > singleCoverage + 20,
      `${label} 4x MSAA should add resolved target edge coverage (${targetCoverage} vs ${singleCoverage})`,
    )
  }

  for (const [label, target] of [
    ['options.target.samples', { texture: {}, samples: 4 }],
    ['options.target.sampleCount', { texture: {}, sampleCount: 4 }],
  ]) {
    const returned = renderRgba(scene, camera, {
      width: 64,
      height: 64,
      target,
      outputColorSpace: THREE.LinearSRGBColorSpace,
    })
    assert.equal(returned, target.data, `${label} should return target.data`)
    assert.equal(target.texture.image.data, target.data, `${label} texture should reference target data`)
    const targetCoverage = intermediateCoverage(target.data)
    assert.ok(
      targetCoverage > singleCoverage + 20,
      `${label} 4x MSAA should add resolved target edge coverage (${targetCoverage} vs ${singleCoverage})`,
    )
  }

  const renderer = new Renderer()
  for (const [label, target] of [
    ['Renderer.setRenderTarget target.samples', { texture: {}, samples: 4 }],
    ['Renderer.setRenderTarget target.sampleCount', { texture: {}, sampleCount: 4 }],
  ]) {
    renderer.setRenderTarget(target)
    const returned = renderer.render(scene, camera, {
      width: 64,
      height: 64,
      outputColorSpace: THREE.LinearSRGBColorSpace,
    })
    assert.equal(returned, target.data, `${label} should return target.data`)
    assert.equal(target.texture.image.data, target.data, `${label} texture should reference target data`)
    const targetCoverage = intermediateCoverage(target.data)
    assert.ok(
      targetCoverage > singleCoverage + 20,
      `${label} 4x MSAA should add resolved target edge coverage (${targetCoverage} vs ${singleCoverage})`,
    )
  }
  renderer.setRenderTarget(null)
})

test('unsupported render target MRT and invalid MSAA requests fail clearly', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0.1, 0.1, 0.1)
  scene.add(new THREE.Mesh(new THREE.BoxGeometry(), new THREE.MeshBasicMaterial({ color: 0x00ffaa })))
  const camera = makeCamera()

  assert.throws(
    () => renderToTarget(scene, camera, null, { width: 32, height: 32 }),
    /target must be a target-like object/i,
  )
  assert.throws(
    () => renderToTarget(scene, camera, [], { width: 32, height: 32 }),
    /target must be a target-like object/i,
  )
  assert.throws(
    () => renderRgba(scene, camera, { width: 32, height: 32, target: 'bad' }),
    /options\.target must be a target-like object/i,
  )
  assert.throws(
    () => renderRgba(scene, camera, { width: 32, height: 32, target: [] }),
    /options\.target must be a target-like object/i,
  )

  const renderer = new Renderer()
  assert.throws(
    () => renderer.setRenderTarget('bad'),
    /Renderer\.setRenderTarget target must be a target-like object/i,
  )
  assert.throws(
    () => renderer.setRenderTarget({}, 6),
    /Renderer\.setRenderTarget activeCubeFace must be an integer from 0 to 5/i,
  )
  assert.throws(
    () => renderer.setRenderTarget({}, 0, -1),
    /Renderer\.setRenderTarget activeMipmapLevel must be a non-negative integer/i,
  )
  assert.throws(
    () => renderer.setRenderTarget({ texture: [{}, {}] }),
    /secondary color attachment.*renderMode/i,
  )

  const arrayOr3DRenderTargetClasses = [
    ['THREE.RenderTargetArray', THREE.RenderTargetArray],
    ['THREE.RenderTarget3D', THREE.RenderTarget3D],
    ['THREE.WebGLArrayRenderTarget', THREE.WebGLArrayRenderTarget],
    ['THREE.WebGL3DRenderTarget', THREE.WebGL3DRenderTarget],
  ]

  for (const [label, TargetClass] of arrayOr3DRenderTargetClasses) {
    const directTarget = new TargetClass(4, 4, 2)
    assert.throws(
      () => renderToTarget(scene, camera, directTarget, { width: 32, height: 32 }),
      /target color texture uses an array or 3D texture/i,
      label,
    )
    assert.throws(
      () => renderRgba(scene, camera, { width: 32, height: 32, target: new TargetClass(4, 4, 2) }),
      /target color texture uses an array or 3D texture/i,
      `${label} options.target`,
    )
    assert.throws(
      () => renderer.setRenderTarget(new TargetClass(4, 4, 2)),
      /target color texture uses an array or 3D texture/i,
      `${label} Renderer.setRenderTarget`,
    )
  }

  const targetCases = [
    [{ image: 'bad' }, /target\.image must be an image-like object/i, 'target image container'],
    [{ texture: 'bad' }, /target\.texture must be a texture-like object/i, 'color texture container'],
    [{ texture: [] }, /target\.texture must contain one texture-like object/i, 'empty texture array'],
    [{ texture: ['bad'] }, /target\.texture\[0\] must be a texture-like object/i, 'texture array element'],
    [{ textures: 'bad' }, /target\.textures must be an array of texture-like objects/i, 'textures container'],
    [{ textures: [] }, /target\.textures must contain one texture-like object/i, 'empty textures array'],
    [{ textures: ['bad'] }, /target\.textures\[0\] must be a texture-like object/i, 'textures array element'],
    [{ depthTexture: 'bad' }, /target\.depthTexture must be a texture-like object/i, 'depth texture container'],
    [{ texture: { image: 'bad' } }, /target\.texture\.image must be an image-like object/i, 'texture image container'],
    [{ texture: { mipmaps: ['bad'] } }, /target\.texture\.mipmaps\[0\] must be an image-like object/i, 'texture mipmap container'],
    [{ texture: { source: 'bad' } }, /target\.texture\.source must be a source-like object/i, 'texture source container'],
    [{ texture: { source: { data: 'bad' } } }, /target\.texture\.source\.data must be an image-like object/i, 'texture source data container'],
    [{ texture: [{}, {}] }, /secondary color attachment.*renderMode/i, 'texture array'],
    [{ textures: [{}, {}] }, /secondary color attachment.*renderMode/i, 'textures array'],
    [{ textures: [{}, { userData: { headlessThreeRenderer: { renderMode: 'albedo' } } }] }, /target color texture\[1\]\.userData\.headlessThreeRenderer\.renderMode must be "color", "mask", "object-id", "normal", or "depth"/i, 'secondary renderMode value'],
    [{ textures: [{}, { userData: { headlessThreeRenderer: 'mask' } }] }, /target color texture\[1\]\.userData\.headlessThreeRenderer must be an object/i, 'secondary renderMode hints'],
    [{ texture: new THREE.DataArrayTexture(new Uint8Array([255, 0, 0, 255]), 1, 1, 1) }, /target color texture uses an array or 3D texture/i, 'color array texture'],
    [{ depthTexture: new THREE.Data3DTexture(new Uint8Array([255, 0, 0, 255]), 1, 1, 1) }, /target\.depthTexture uses an array or 3D texture/i, 'depth 3D texture'],
    [{ texture: new THREE.FramebufferTexture(1, 1) }, /target color texture uses a FramebufferTexture/i, 'color framebuffer texture'],
    [{ depthTexture: new THREE.FramebufferTexture(1, 1) }, /target\.depthTexture uses a FramebufferTexture/i, 'depth framebuffer texture'],
    [{ texture: new THREE.DepthTexture(1, 1) }, /target color texture uses a DepthTexture as a color attachment/i, 'color depth texture'],
    [{ texture: new THREE_WEBGPU.StorageTexture(1, 1) }, /target color texture uses a StorageTexture.*scene-oriented output contract/i, 'color storage texture'],
    [{ depthTexture: new THREE_WEBGPU.StorageTexture(1, 1) }, /target\.depthTexture uses a StorageTexture.*scene-oriented output contract/i, 'depth storage texture'],
    [{ texture: new THREE.CompressedTexture([], 1, 1, THREE.RGBAFormat) }, /target color texture uses a compressed texture/i, 'color compressed texture'],
    [{ depthTexture: new THREE.CompressedTexture([], 1, 1, THREE.RGBAFormat) }, /target\.depthTexture uses a compressed texture/i, 'depth compressed texture'],
    [{ texture: { format: THREE.RGBA_S3TC_DXT5_Format } }, /target color texture format uses a compressed texture format/i, 'color compressed format'],
    [{ depthTexture: { format: THREE.RGBA_S3TC_DXT5_Format } }, /target\.depthTexture\.format uses a compressed texture format/i, 'depth compressed format'],
    [{ texture: { isCubeTexture: true } }, /target color texture uses a cube texture.*THREE\.CubeCamera/i, 'regular camera cube color texture'],
    [{ depthTexture: { isCubeTexture: true } }, /target\.depthTexture uses a cube texture.*THREE\.CubeCamera/i, 'regular camera cube depth texture'],
    [{ samples: 2 }, /MSAA sample count 2.*not supported/i, 'target samples'],
    [{ sampleCount: 8 }, /MSAA sample count 8.*not supported/i, 'target sampleCount'],
    [{ texture: { format: THREE.DepthFormat } }, /target color texture format .*not supported.*AlphaFormat.*LuminanceFormat.*LuminanceAlphaFormat.*RedFormat.*RedIntegerFormat.*RGFormat.*RGIntegerFormat.*RGBFormat.*RGBIntegerFormat.*RGBAFormat.*RGBAIntegerFormat/i, 'color texture format'],
    [{ texture: { type: THREE.UnsignedInt248Type } }, /target color texture type .*not supported.*UnsignedByteType.*ByteType.*ShortType.*UnsignedShortType.*IntType.*UnsignedIntType.*HalfFloatType.*FloatType.*UnsignedShort4444Type.*UnsignedShort5551Type.*UnsignedInt101111Type.*UnsignedInt5999Type/i, 'color texture type'],
    [{ depthTexture: { type: THREE.ByteType } }, /target\.depthTexture\.type .*not supported/i, 'depth texture type'],
    [{ depthTexture: { format: THREE.RGBAFormat } }, /target\.depthTexture\.format .*not supported/i, 'depth texture format'],
    [{ depthTexture: { type: THREE.FloatType, format: THREE.DepthStencilFormat } }, /DepthStencilFormat.*UnsignedInt248Type/i, 'depth-stencil format with scalar type'],
    [{ depthTexture: { type: THREE.UnsignedInt248Type, format: THREE.DepthFormat } }, /DepthFormat.*UnsignedInt248Type/i, 'depth format with packed depth-stencil type'],
  ]

  for (const [target, pattern, label] of targetCases) {
    assert.throws(
      () => renderToTarget(scene, camera, target, { width: 32, height: 32 }),
      pattern,
      label,
    )
  }

  const optionsTargetCases = [
    [{ texture: [{}, {}] }, /secondary color attachment.*renderMode/i, 'options.target texture array'],
    [{ texture: new THREE.DataArrayTexture(new Uint8Array([255, 0, 0, 255]), 1, 1, 1) }, /target color texture uses an array or 3D texture/i, 'options.target color array texture'],
    [{ texture: new THREE.FramebufferTexture(1, 1) }, /target color texture uses a FramebufferTexture/i, 'options.target color framebuffer texture'],
    [{ texture: new THREE.DepthTexture(1, 1) }, /target color texture uses a DepthTexture as a color attachment/i, 'options.target color depth texture'],
    [{ texture: new THREE_WEBGPU.StorageTexture(1, 1) }, /target color texture uses a StorageTexture.*scene-oriented output contract/i, 'options.target color storage texture'],
    [{ depthTexture: new THREE_WEBGPU.StorageTexture(1, 1) }, /target\.depthTexture uses a StorageTexture.*scene-oriented output contract/i, 'options.target depth storage texture'],
    [{ texture: new THREE.CompressedTexture([], 1, 1, THREE.RGBAFormat) }, /target color texture uses a compressed texture/i, 'options.target compressed color texture'],
    [{ texture: { format: THREE.RGBA_S3TC_DXT5_Format } }, /target color texture format uses a compressed texture format/i, 'options.target compressed color format'],
    [{ depthTexture: { format: THREE.RGBA_S3TC_DXT5_Format } }, /target\.depthTexture\.format uses a compressed texture format/i, 'options.target compressed depth format'],
    [{ sampleCount: 8 }, /MSAA sample count 8.*not supported/i, 'options.target sampleCount'],
    [{ texture: { format: THREE.DepthFormat } }, /target color texture format .*not supported.*AlphaFormat.*LuminanceFormat.*LuminanceAlphaFormat.*RedFormat.*RedIntegerFormat.*RGFormat.*RGIntegerFormat.*RGBFormat.*RGBIntegerFormat.*RGBAFormat.*RGBAIntegerFormat/i, 'options.target color texture format'],
    [{ depthTexture: { type: THREE.ByteType } }, /target\.depthTexture\.type .*not supported/i, 'options.target depth texture type'],
    [{ depthTexture: { format: THREE.RGBAFormat } }, /target\.depthTexture\.format .*not supported/i, 'options.target depth texture format'],
    [{ depthTexture: { type: THREE.FloatType, format: THREE.DepthStencilFormat } }, /DepthStencilFormat.*UnsignedInt248Type/i, 'options.target depth-stencil format with scalar type'],
    [{ depthTexture: { type: THREE.UnsignedInt248Type, format: THREE.DepthFormat } }, /DepthFormat.*UnsignedInt248Type/i, 'options.target depth format with packed depth-stencil type'],
  ]

  for (const [target, pattern, label] of optionsTargetCases) {
    assert.throws(
      () => renderRgba(scene, camera, { width: 32, height: 32, target }),
      pattern,
      label,
    )
  }

  for (const options of [{ samples: 2 }, { sampleCount: 8 }]) {
    assert.throws(
      () => renderRgba(scene, camera, { width: 32, height: 32, ...options }),
      /MSAA sample count .*not supported/i,
      JSON.stringify(options),
    )
  }
})

test('post-processing options modify the final image', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(1, 0, 0)
  const camera = makeCamera()

  const base = renderRgba(scene, camera, { width: 64, height: 64 })
  const processed = renderRgba(scene, camera, {
    width: 64,
    height: 64,
    postProcessing: { invert: 1, saturation: 1.5, vignette: 0.25 },
  })
  const diff = meanAbsDiff(base, processed)
  const mean = meanRgba(processed)
  assert.ok(diff > 20, `expected post processing to change image, diff=${diff.toFixed(2)}`)
  assert.ok(mean.g > mean.r, `inverted red background should have stronger green than red (${mean.g} vs ${mean.r})`)
})

test('post-processing exposure contrast and grayscale controls modify output', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0.25, 0.5, 0.75)
  const camera = makeCamera()
  const options = { width: 64, height: 64, outputColorSpace: THREE.LinearSRGBColorSpace }

  const base = meanRgba(renderRgba(scene, camera, options))
  const exposed = meanRgba(renderRgba(scene, camera, {
    ...options,
    postProcessing: { exposure: 1 },
  }))
  const contrasted = meanRgba(renderRgba(scene, camera, {
    ...options,
    postProcessing: { contrast: 2 },
  }))
  const grayscale = meanRgba(renderRgba(scene, camera, {
    ...options,
    postProcessing: { grayscale: true },
  }))

  assert.ok(exposed.r > base.r + 20, `exposure should brighten red (${exposed.r} vs ${base.r})`)
  assert.ok(exposed.g > base.g + 20, `exposure should brighten green (${exposed.g} vs ${base.g})`)
  assert.ok(contrasted.r < base.r - 20, `contrast should darken below-mid red (${contrasted.r} vs ${base.r})`)
  assert.ok(contrasted.b > base.b + 20, `contrast should brighten above-mid blue (${contrasted.b} vs ${base.b})`)
  assert.ok(Math.max(grayscale.r, grayscale.g, grayscale.b) - Math.min(grayscale.r, grayscale.g, grayscale.b) < 3, `boolean grayscale should equalize color channels (${grayscale.r}, ${grayscale.g}, ${grayscale.b})`)
})

test('post-processing enabled false bypasses configured effects', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0.25, 0.5, 0.75)
  const camera = makeCamera()
  const options = { width: 32, height: 32, outputColorSpace: THREE.LinearSRGBColorSpace }

  const base = renderRgba(scene, camera, options)
  const disabled = renderRgba(scene, camera, {
    ...options,
    postProcessing: {
      enabled: false,
      exposure: 4,
      contrast: 4,
      grayscale: true,
      invert: true,
      saturation: 0,
      vignette: 1,
    },
  })

  assert.deepEqual(disabled, base, 'postProcessing.enabled=false should ignore configured effects')
})

test('reusable renderer updates cached background and post-processing uniforms', () => {
  const renderer = new Renderer()
  const camera = makeCamera()

  const backgroundScene = new THREE.Scene()
  backgroundScene.background = solidTexture(0, 255, 0)
  const backgroundOptions = { width: 64, height: 64, format: 'rgba' }
  const dimmed = meanRgba(renderer.render(backgroundScene, camera, {
    ...backgroundOptions,
    backgroundIntensity: 0.25,
  }))
  const full = meanRgba(renderer.render(backgroundScene, camera, {
    ...backgroundOptions,
    backgroundIntensity: 1,
  }))
  const dimmedAgain = meanRgba(renderer.render(backgroundScene, camera, {
    ...backgroundOptions,
    backgroundIntensity: 0.25,
  }))
  assert.ok(full.g > dimmed.g + 60, `updated background uniform should brighten cached texture background (${full.g} vs ${dimmed.g})`)
  assert.ok(Math.abs(dimmedAgain.g - dimmed.g) < 4, `cached background uniform should update back to dimmed intensity (${dimmedAgain.g} vs ${dimmed.g})`)

  const postScene = new THREE.Scene()
  postScene.background = new THREE.Color(1, 0, 0)
  const postOptions = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
  }
  const inverted = meanRgba(renderer.render(postScene, camera, {
    ...postOptions,
    postProcessing: { invert: 1 },
  }))
  const grayscale = meanRgba(renderer.render(postScene, camera, {
    ...postOptions,
    postProcessing: { grayscale: true },
  }))
  postScene.background = new THREE.Color(0, 0, 1)
  const invertedBlue = meanRgba(renderer.render(postScene, camera, {
    ...postOptions,
    postProcessing: { invert: 1 },
  }))
  postScene.background = new THREE.Color(1, 0, 0)
  const invertedAgain = meanRgba(renderer.render(postScene, camera, {
    ...postOptions,
    postProcessing: { invert: 1 },
  }))

  assert.ok(inverted.g > inverted.r + 80 && inverted.b > inverted.r + 80, `invert uniform should turn red toward cyan (${inverted.r}, ${inverted.g}, ${inverted.b})`)
  assert.ok(Math.max(grayscale.r, grayscale.g, grayscale.b) - Math.min(grayscale.r, grayscale.g, grayscale.b) < 3, `grayscale uniform should replace prior invert settings (${grayscale.r}, ${grayscale.g}, ${grayscale.b})`)
  assert.ok(invertedBlue.r > invertedBlue.b + 80 && invertedBlue.g > invertedBlue.b + 80, `cached post bind group should sample updated blue scene color as yellow after invert (${invertedBlue.r}, ${invertedBlue.g}, ${invertedBlue.b})`)
  assert.ok(Math.abs(invertedAgain.g - inverted.g) < 4 && Math.abs(invertedAgain.b - inverted.b) < 4, `post uniform buffer should update back to invert settings (${invertedAgain.r}, ${invertedAgain.g}, ${invertedAgain.b})`)
})

test('reusable renderer reflects mutated background texture bytes', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  const camera = makeCamera()
  const data = new Uint8Array([255, 0, 0, 255])
  const background = new THREE.DataTexture(data, 1, 1, THREE.RGBAFormat)
  background.needsUpdate = true
  scene.background = background

  const options = { width: 64, height: 64, format: 'rgba' }
  const sample = () => meanRgba(renderer.render(scene, camera, options))

  const red = sample()
  data.set([0, 255, 0, 255])
  background.needsUpdate = true
  const green = sample()
  data.set([255, 0, 0, 255])
  background.needsUpdate = true
  const redAgain = sample()

  assert.ok(red.r > red.g + 80, `initial background texture should render red (${red.r}, ${red.g}, ${red.b})`)
  assert.ok(green.g > green.r + 80, `mutated background texture should render green (${green.r}, ${green.g}, ${green.b})`)
  assert.ok(redAgain.r > redAgain.g + 80, `background texture upload should update back to red (${redAgain.r}, ${redAgain.g}, ${redAgain.b})`)
})

test('reusable renderer reflects mutated mesh material texture and transform state', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const texture = rgbaTexture([255, 255, 255, 255], 1, 1)
  const material = new THREE.MeshBasicMaterial({ color: 0xff0000, map: texture })
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.75, 0.75), material)
  mesh.position.x = -0.5
  scene.add(mesh)

  const options = { width: 64, height: 64, format: 'rgba' }
  const first = renderer.render(scene, camera, options)
  const firstLeft = meanRegion(first, 64, 64, 8, 24, 28, 40)
  const firstRight = meanRegion(first, 64, 64, 36, 24, 56, 40)

  assert.ok(firstLeft.r > 180, `initial material color should render red on the left (${firstLeft.r}, ${firstLeft.g}, ${firstLeft.b})`)
  assert.ok(firstLeft.g < 40 && firstLeft.b < 40, `initial left region should not include stale green/blue (${firstLeft.r}, ${firstLeft.g}, ${firstLeft.b})`)
  assert.ok(firstRight.r < 20 && firstRight.g < 20 && firstRight.b < 20, `initial right region should remain background (${firstRight.r}, ${firstRight.g}, ${firstRight.b})`)

  texture.image.data.set([0, 255, 0, 255])
  texture.needsUpdate = true
  material.color.set(0xffffff)
  mesh.position.x = 0.5

  const second = renderer.render(scene, camera, options)
  const secondLeft = meanRegion(second, 64, 64, 8, 24, 28, 40)
  const secondRight = meanRegion(second, 64, 64, 36, 24, 56, 40)

  assert.ok(secondLeft.r < 20 && secondLeft.g < 20 && secondLeft.b < 20, `updated transform should clear the previous left region (${secondLeft.r}, ${secondLeft.g}, ${secondLeft.b})`)
  assert.ok(secondRight.g > 180, `updated texture data should render green on the right (${secondRight.r}, ${secondRight.g}, ${secondRight.b})`)
  assert.ok(secondRight.g > secondRight.r + 50 && secondRight.g > secondRight.b + 80, `updated material and texture state should produce a green-dominant right region (${secondRight.r}, ${secondRight.g}, ${secondRight.b})`)

  texture.image.data.set([255, 255, 255, 255])
  texture.needsUpdate = true
  material.color.set(0xff0000)
  mesh.position.x = -0.5

  const third = renderer.render(scene, camera, options)
  const thirdLeft = meanRegion(third, 64, 64, 8, 24, 28, 40)
  const thirdRight = meanRegion(third, 64, 64, 36, 24, 56, 40)

  assert.ok(thirdLeft.r > 180, `dynamic mesh uniform slot should update back to red on the left (${thirdLeft.r}, ${thirdLeft.g}, ${thirdLeft.b})`)
  assert.ok(thirdLeft.g < 40 && thirdLeft.b < 40, `updated uniform slot should not retain prior green texture state (${thirdLeft.r}, ${thirdLeft.g}, ${thirdLeft.b})`)
  assert.ok(thirdRight.r < 20 && thirdRight.g < 20 && thirdRight.b < 20, `updated transform should clear the previous right region (${thirdRight.r}, ${thirdRight.g}, ${thirdRight.b})`)
})

test('reusable renderer reuses cached material texture payload until texture version changes', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const sourceData = new Uint8Array([255, 255, 255])
  let textureReads = 0
  const trackedData = new Proxy(sourceData, {
    get(target, property) {
      if (typeof property === 'string' && /^(0|[1-9]\d*)$/.test(property)) {
        textureReads += 1
      }
      return Reflect.get(target, property, target)
    },
    set(target, property, value) {
      return Reflect.set(target, property, value, target)
    },
  })
  const texture = new THREE.DataTexture(trackedData, 1, 1, THREE.RGBFormat)
  texture.needsUpdate = true

  const material = new THREE.MeshBasicMaterial({ color: 0xff0000, map: texture })
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.75, 0.75), material)
  mesh.frustumCulled = false
  mesh.position.x = -0.5
  scene.add(mesh)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  const first = renderer.render(scene, camera, options)
  const firstLeft = meanRegion(first, 64, 64, 8, 24, 28, 40)
  const readsAfterFirstRender = textureReads
  assert.ok(firstLeft.r > 180 && firstLeft.g < 40, `initial cached texture render should be red (${firstLeft.r}, ${firstLeft.g}, ${firstLeft.b})`)
  assert.ok(readsAfterFirstRender > 0, 'initial render should extract texture payload bytes')

  material.color.set(0x00ff00)
  mesh.position.x = 0.5
  const second = renderer.render(scene, camera, options)
  const secondRight = meanRegion(second, 64, 64, 36, 24, 56, 40)
  assert.ok(secondRight.g > secondRight.r + 80, `material and transform animation should remain live while texture payload is cached (${secondRight.r}, ${secondRight.g}, ${secondRight.b})`)
  assert.equal(textureReads, readsAfterFirstRender, 'material and transform animation should reuse cached texture payload extraction')

  sourceData.set([0, 0, 255])
  texture.needsUpdate = true
  material.color.set(0xffffff)
  mesh.position.x = -0.5
  const third = renderer.render(scene, camera, options)
  const thirdLeft = meanRegion(third, 64, 64, 8, 24, 28, 40)
  assert.ok(thirdLeft.b > thirdLeft.r + 120, `texture version changes should render updated blue payload (${thirdLeft.r}, ${thirdLeft.g}, ${thirdLeft.b})`)
  assert.ok(textureReads > readsAfterFirstRender, 'texture version changes should invalidate cached texture payload extraction')
})

test('reusable renderer reuses cached base texture sampler state until texture state changes', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const texture = rgbaTexture([255, 255, 255, 255], 1, 1)
  texture.rotation = 0.37
  const material = new THREE.MeshBasicMaterial({ color: 0xff0000, map: texture })
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.75, 0.75), material)
  mesh.frustumCulled = false
  scene.add(mesh)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  const originalCos = Math.cos
  let rotationCosCalls = 0
  Math.cos = (value) => {
    if (value === texture.rotation) {
      rotationCosCalls += 1
    }
    return originalCos(value)
  }
  try {
    const first = renderer.render(scene, camera, options)
    const firstCenter = meanRegion(first, 64, 64, 24, 24, 40, 40)
    const callsAfterFirstRender = rotationCosCalls
    assert.ok(firstCenter.r > 180 && firstCenter.g < 40, `initial mapped material should render red (${firstCenter.r}, ${firstCenter.g}, ${firstCenter.b})`)
    assert.ok(callsAfterFirstRender > 0, 'initial render should compute texture transform state')

    material.color.set(0x00ff00)
    const second = renderer.render(scene, camera, options)
    const secondCenter = meanRegion(second, 64, 64, 24, 24, 40, 40)
    assert.ok(secondCenter.g > secondCenter.r + 80, `material color should remain live while base texture state is cached (${secondCenter.r}, ${secondCenter.g}, ${secondCenter.b})`)
    assert.equal(rotationCosCalls, callsAfterFirstRender, 'material-only animation should reuse cached base texture sampler state')

    texture.rotation = 0.61
    renderer.render(scene, camera, options)
    const callsAfterTransformStateChange = rotationCosCalls
    assert.ok(callsAfterTransformStateChange > callsAfterFirstRender, 'texture transform changes should invalidate cached base texture sampler state')

    texture.wrapS = THREE.RepeatWrapping
    renderer.render(scene, camera, options)
    assert.ok(rotationCosCalls > callsAfterTransformStateChange, 'texture sampler changes should invalidate cached base texture sampler state')
  } finally {
    Math.cos = originalCos
  }
})

test('reusable renderer reuses cached material render state until render state changes', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const material = new THREE.MeshBasicMaterial({ color: 0xff0000 })
  material.stencilRef = 7.25
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.75, 0.75), material)
  mesh.frustumCulled = false
  scene.add(mesh)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  const originalTrunc = Math.trunc
  let stencilRefTruncCalls = 0
  Math.trunc = (value) => {
    if (value === material.stencilRef) {
      stencilRefTruncCalls += 1
    }
    return originalTrunc(value)
  }
  try {
    const first = renderer.render(scene, camera, options)
    const firstCenter = meanRegion(first, 64, 64, 24, 24, 40, 40)
    const callsAfterFirstRender = stencilRefTruncCalls
    assert.ok(firstCenter.r > 180 && firstCenter.g < 40, `initial material should render red (${firstCenter.r}, ${firstCenter.g}, ${firstCenter.b})`)
    assert.ok(callsAfterFirstRender > 0, 'initial render should extract material render state')

    material.color.set(0x00ff00)
    const second = renderer.render(scene, camera, options)
    const secondCenter = meanRegion(second, 64, 64, 24, 24, 40, 40)
    assert.ok(secondCenter.g > secondCenter.r + 80, `material color should remain live while render state is cached (${secondCenter.r}, ${secondCenter.g}, ${secondCenter.b})`)
    assert.equal(stencilRefTruncCalls, callsAfterFirstRender, 'material-color animation should reuse cached material render state')

    material.stencilRef = 11.75
    renderer.render(scene, camera, options)
    assert.ok(stencilRefTruncCalls > callsAfterFirstRender, 'render-state changes should invalidate cached material render state')
  } finally {
    Math.trunc = originalTrunc
  }
})

test('reusable renderer reuses cached material scalar feature state until scalar changes', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const material = new THREE.MeshBasicMaterial({ color: 0xff0000 })
  material.thickness = 0.42
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.75, 0.75), material)
  mesh.frustumCulled = false
  scene.add(mesh)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  const originalMax = Math.max
  let thicknessMaxCalls = 0
  Math.max = (...values) => {
    if (values[0] === 0 && values[1] === material.thickness) {
      thicknessMaxCalls += 1
    }
    return originalMax(...values)
  }
  try {
    const first = renderer.render(scene, camera, options)
    const firstCenter = meanRegion(first, 64, 64, 24, 24, 40, 40)
    const callsAfterFirstRender = thicknessMaxCalls
    assert.ok(firstCenter.r > 180 && firstCenter.g < 40, `initial scalar-feature material should render red (${firstCenter.r}, ${firstCenter.g}, ${firstCenter.b})`)
    assert.ok(callsAfterFirstRender > 0, 'initial render should extract material scalar feature state')

    material.color.set(0x00ff00)
    const second = renderer.render(scene, camera, options)
    const secondCenter = meanRegion(second, 64, 64, 24, 24, 40, 40)
    assert.ok(secondCenter.g > secondCenter.r + 80, `material color should remain live while scalar feature state is cached (${secondCenter.r}, ${secondCenter.g}, ${secondCenter.b})`)
    assert.equal(thicknessMaxCalls, callsAfterFirstRender, 'material-color animation should reuse cached material scalar feature state')

    material.thickness = 0.73
    renderer.render(scene, camera, options)
    assert.ok(thicknessMaxCalls > callsAfterFirstRender, 'material scalar changes should invalidate cached scalar feature state')
  } finally {
    Math.max = originalMax
  }
})

test('reusable renderer reuses cached PBR map sampler state until texture state changes', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const texture = rgbaTexture([255, 255, 255, 255], 1, 1)
  texture.rotation = 0.37
  const material = new THREE.MeshStandardMaterial({ color: 0x000000, roughness: 1, metalness: 0 })
  material.emissive.set(0xff0000)
  material.emissiveIntensity = 1
  material.emissiveMap = texture
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.75, 0.75), material)
  mesh.frustumCulled = false
  scene.add(mesh)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  const originalCos = Math.cos
  let rotationCosCalls = 0
  Math.cos = (value) => {
    if (value === texture.rotation) {
      rotationCosCalls += 1
    }
    return originalCos(value)
  }
  try {
    const first = renderer.render(scene, camera, options)
    const firstCenter = meanRegion(first, 64, 64, 24, 24, 40, 40)
    const callsAfterFirstRender = rotationCosCalls
    assert.ok(firstCenter.r > 120 && firstCenter.g < 40, `initial emissive map should render red (${firstCenter.r}, ${firstCenter.g}, ${firstCenter.b})`)
    assert.ok(callsAfterFirstRender > 0, 'initial render should compute PBR map texture state')

    material.emissive.set(0x00ff00)
    const second = renderer.render(scene, camera, options)
    const secondCenter = meanRegion(second, 64, 64, 24, 24, 40, 40)
    assert.ok(secondCenter.g > secondCenter.r + 60, `PBR color slots should remain live while PBR map state is cached (${secondCenter.r}, ${secondCenter.g}, ${secondCenter.b})`)
    assert.equal(rotationCosCalls, callsAfterFirstRender, 'material-only animation should reuse cached PBR map sampler state')

    texture.rotation = 0.61
    renderer.render(scene, camera, options)
    const callsAfterTransformStateChange = rotationCosCalls
    assert.ok(callsAfterTransformStateChange > callsAfterFirstRender, 'PBR map texture transform changes should invalidate cached sampler state')

    texture.wrapT = THREE.RepeatWrapping
    renderer.render(scene, camera, options)
    assert.ok(rotationCosCalls > callsAfterTransformStateChange, 'PBR map texture sampler changes should invalidate cached sampler state')
  } finally {
    Math.cos = originalCos
  }
})

test('reusable renderer reuses cached CSS material color extraction until color changes', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const material = new THREE.MeshBasicMaterial()
  material.color = 'rgb(255, 0, 0)'
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.75, 0.75), material)
  mesh.frustumCulled = false
  scene.add(mesh)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  const { Color: RequiredThreeColor } = cjsRequire('three')
  const originalSetStyle = RequiredThreeColor.prototype.setStyle
  let cssParseCalls = 0
  RequiredThreeColor.prototype.setStyle = function setStyle(style, ...args) {
    if (style === material.color) {
      cssParseCalls += 1
    }
    return originalSetStyle.call(this, style, ...args)
  }
  try {
    const first = renderer.render(scene, camera, options)
    const firstCenter = meanRegion(first, 64, 64, 24, 24, 40, 40)
    const parseCallsAfterFirstRender = cssParseCalls
    assert.ok(firstCenter.r > 180 && firstCenter.g < 40, `initial CSS material color should render red (${firstCenter.r}, ${firstCenter.g}, ${firstCenter.b})`)
    assert.ok(parseCallsAfterFirstRender > 0, 'initial render should parse CSS material color')

    renderer.render(scene, camera, options)
    assert.equal(cssParseCalls, parseCallsAfterFirstRender, 'unchanged CSS material color should reuse cached color extraction')

    material.color = 'rgb(0, 255, 0)'
    const third = renderer.render(scene, camera, options)
    const thirdCenter = meanRegion(third, 64, 64, 24, 24, 40, 40)
    assert.ok(thirdCenter.g > thirdCenter.r + 80, `CSS material color changes should render updated green (${thirdCenter.r}, ${thirdCenter.g}, ${thirdCenter.b})`)
    assert.ok(cssParseCalls > parseCallsAfterFirstRender, 'CSS material color changes should invalidate cached color extraction')
  } finally {
    RequiredThreeColor.prototype.setStyle = originalSetStyle
  }
})

