test('reusable renderer reuses cached static line and point geometry until attributes change', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  function instrumentPosition(attribute) {
    const originalGetX = attribute.getX.bind(attribute)
    let reads = 0
    attribute.getX = (index) => {
      reads += 1
      return originalGetX(index)
    }
    return () => reads
  }

  const lineGeometry = new THREE.BufferGeometry()
  lineGeometry.setAttribute('position', new THREE.Float32BufferAttribute([
    -0.7, -0.25, 0,
    -0.2, -0.25, 0,
  ], 3))
  const linePosition = lineGeometry.getAttribute('position')
  const lineReads = instrumentPosition(linePosition)
  const lineMaterial = new THREE.LineBasicMaterial({ color: 0xff0000 })
  const line = new THREE.LineSegments(lineGeometry, lineMaterial)
  line.frustumCulled = false
  scene.add(line)

  const pointGeometry = new THREE.BufferGeometry()
  pointGeometry.setAttribute('position', new THREE.Float32BufferAttribute([
    0.2, 0.25, 0,
    0.55, 0.25, 0,
  ], 3))
  const pointPosition = pointGeometry.getAttribute('position')
  const pointReads = instrumentPosition(pointPosition)
  const pointMaterial = new THREE.PointsMaterial({ color: 0x00ff00, size: 10, sizeAttenuation: false })
  const points = new THREE.Points(pointGeometry, pointMaterial)
  points.frustumCulled = false
  scene.add(points)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  renderer.render(scene, camera, options)
  const lineReadsAfterFirstRender = lineReads()
  const pointReadsAfterFirstRender = pointReads()
  assert.ok(lineReadsAfterFirstRender > 0, 'initial render should extract line geometry')
  assert.ok(pointReadsAfterFirstRender > 0, 'initial render should extract point geometry')

  line.position.x += 0.1
  points.position.x -= 0.1
  lineMaterial.color.set(0x0000ff)
  pointMaterial.color.set(0xff00ff)
  renderer.render(scene, camera, options)
  assert.equal(lineReads(), lineReadsAfterFirstRender, 'line transform/material animation should reuse cached static geometry extraction')
  assert.equal(pointReads(), pointReadsAfterFirstRender, 'point transform/material animation should reuse cached static geometry extraction')

  linePosition.array[0] += 0.05
  linePosition.needsUpdate = true
  renderer.render(scene, camera, options)
  const lineReadsAfterLineUpdate = lineReads()
  assert.ok(lineReadsAfterLineUpdate > lineReadsAfterFirstRender, 'line attribute version changes should invalidate cached geometry extraction')
  assert.equal(pointReads(), pointReadsAfterFirstRender, 'line invalidation should not force unrelated point geometry extraction')

  pointPosition.array[0] -= 0.05
  pointPosition.needsUpdate = true
  renderer.render(scene, camera, options)
  assert.ok(pointReads() > pointReadsAfterFirstRender, 'point attribute version changes should invalidate cached geometry extraction')
  assert.equal(lineReads(), lineReadsAfterLineUpdate, 'point invalidation should not force unrelated line geometry extraction')
})

test('reusable renderer reuses cached dashed-line expansion until dash inputs change', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute([
    -0.8, 0, 0,
    0.8, 0, 0,
  ], 3))
  geometry.setAttribute('lineDistance', new THREE.Float32BufferAttribute([0, 1.6], 1))

  const lineDistance = geometry.getAttribute('lineDistance')
  const originalGetX = lineDistance.getX.bind(lineDistance)
  let lineDistanceReads = 0
  lineDistance.getX = (index) => {
    lineDistanceReads += 1
    return originalGetX(index)
  }

  const material = new THREE.LineDashedMaterial({
    color: 0xff0000,
    dashSize: 0.25,
    gapSize: 0,
    linewidth: 8,
    scale: 1,
  })
  const line = new THREE.Line(geometry, material)
  line.frustumCulled = false
  scene.add(line)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  const first = renderer.render(scene, camera, options)
  const firstCenter = meanRegion(first, 64, 64, 28, 28, 36, 36)
  const readsAfterFirstRender = lineDistanceReads
  assert.ok(firstCenter.r > 180 && firstCenter.g < 40, `initial dashed line should render red (${firstCenter.r}, ${firstCenter.g}, ${firstCenter.b})`)
  assert.ok(readsAfterFirstRender > 0, 'initial render should read lineDistance while expanding dashed line geometry')

  material.color.set(0x00ff00)
  line.position.x += 0.05
  const second = renderer.render(scene, camera, options)
  const secondCenter = meanRegion(second, 64, 64, 28, 28, 36, 36)
  assert.ok(secondCenter.g > secondCenter.r + 80, `material color should remain live while dashed-line expansion is cached (${secondCenter.r}, ${secondCenter.g}, ${secondCenter.b})`)
  assert.equal(lineDistanceReads, readsAfterFirstRender, 'material/transform animation should reuse cached dashed-line expansion')

  material.scale = 2
  renderer.render(scene, camera, options)
  const readsAfterScaleStateChange = lineDistanceReads
  assert.ok(readsAfterScaleStateChange > readsAfterFirstRender, 'dash scale changes should invalidate cached dashed-line expansion')

  material.gapSize = 0.15
  renderer.render(scene, camera, options)
  const readsAfterDashStateChange = lineDistanceReads
  assert.ok(readsAfterDashStateChange > readsAfterScaleStateChange, 'dash-state changes should invalidate cached dashed-line expansion')

  lineDistance.array[1] = 1.4
  lineDistance.needsUpdate = true
  renderer.render(scene, camera, options)
  assert.ok(lineDistanceReads > readsAfterDashStateChange, 'lineDistance version changes should invalidate cached dashed-line expansion')
})

test('reusable renderer reuses cached instanced dashed-line expansion until inputs change', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)

  const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10)
  camera.position.set(0, 0, 2)
  camera.lookAt(0, 0, 0)

  const geometry = new THREE.InstancedBufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute([
    -0.2, 0, 0,
    0.2, 0, 0,
  ], 3))
  const offset = new THREE.InstancedBufferAttribute(new Float32Array([
    -0.35, 0, 0,
    0.35, 0, 0,
  ]), 3)
  geometry.setAttribute('instanceOffset', offset)
  geometry.setAttribute('lineDistance', new THREE.Float32BufferAttribute([0, 0.4], 1))
  geometry.instanceCount = 2

  const originalOffsetGetX = offset.getX.bind(offset)
  let offsetReads = 0
  offset.getX = (index) => {
    offsetReads += 1
    return originalOffsetGetX(index)
  }

  const lineDistance = geometry.getAttribute('lineDistance')
  const originalLineDistanceGetX = lineDistance.getX.bind(lineDistance)
  let lineDistanceReads = 0
  lineDistance.getX = (index) => {
    lineDistanceReads += 1
    return originalLineDistanceGetX(index)
  }

  const material = new THREE.LineDashedMaterial({
    color: 0xff0000,
    dashSize: 0.2,
    gapSize: 0,
    linewidth: 8,
    scale: 1,
  })
  const line = new THREE.LineSegments(geometry, material)
  line.frustumCulled = false
  scene.add(line)

  const options = {
    width: 64,
    height: 64,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
    sortObjects: false,
  }

  renderer.render(scene, camera, options)
  const offsetReadsAfterFirstRender = offsetReads
  const lineDistanceReadsAfterFirstRender = lineDistanceReads
  assert.ok(offsetReadsAfterFirstRender > 0, 'initial render should read instanced dashed-line offsets')
  assert.ok(lineDistanceReadsAfterFirstRender > 0, 'initial render should read instanced dashed-line distances')

  material.color.set(0x00ff00)
  line.position.y += 0.05
  renderer.render(scene, camera, options)
  assert.equal(offsetReads, offsetReadsAfterFirstRender, 'material/transform animation should reuse cached instanced dashed-line offsets')
  assert.equal(lineDistanceReads, lineDistanceReadsAfterFirstRender, 'material/transform animation should reuse cached instanced dashed-line distances')

  material.scale = 2
  renderer.render(scene, camera, options)
  const offsetReadsAfterScaleStateChange = offsetReads
  const lineDistanceReadsAfterScaleStateChange = lineDistanceReads
  assert.ok(offsetReadsAfterScaleStateChange > offsetReadsAfterFirstRender, 'dash scale changes should invalidate cached instanced dashed-line offsets')
  assert.ok(lineDistanceReadsAfterScaleStateChange > lineDistanceReadsAfterFirstRender, 'dash scale changes should invalidate cached instanced dashed-line distances')

  material.gapSize = 0.1
  renderer.render(scene, camera, options)
  const offsetReadsAfterDashStateChange = offsetReads
  const lineDistanceReadsAfterDashStateChange = lineDistanceReads
  assert.ok(offsetReadsAfterDashStateChange > offsetReadsAfterScaleStateChange, 'dash-state changes should invalidate cached instanced dashed-line offsets')
  assert.ok(lineDistanceReadsAfterDashStateChange > lineDistanceReadsAfterScaleStateChange, 'dash-state changes should invalidate cached instanced dashed-line distances')

  offset.array[0] = -0.3
  offset.needsUpdate = true
  renderer.render(scene, camera, options)
  const lineDistanceReadsAfterOffsetUpdate = lineDistanceReads
  assert.ok(offsetReads > offsetReadsAfterDashStateChange, 'instanced offset version changes should invalidate cached dashed-line expansion')

  lineDistance.array[1] = 0.55
  lineDistance.needsUpdate = true
  renderer.render(scene, camera, options)
  assert.ok(lineDistanceReads > lineDistanceReadsAfterOffsetUpdate, 'lineDistance version changes should invalidate cached instanced dashed-line expansion')
})

