test('render option null background clears scene backgrounds', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(1, 0, 0)
  const camera = makeCamera()

  const sceneBackground = meanRgba(renderRgba(scene, camera, { width: 64, height: 64 }))
  scene.backgroundIntensity = 'ignored'
  scene.backgroundRotation = new THREE.Euler(0, Math.PI / 4, 0)
  const cleared = meanRgba(renderRgba(scene, camera, { width: 64, height: 64, background: null }))

  assert.ok(sceneBackground.r > 200, `scene color background should render red (${sceneBackground.r})`)
  assert.ok(cleared.r < sceneBackground.r - 120, `options.background null should clear scene color background (${cleared.r} vs ${sceneBackground.r})`)
  assert.ok(cleared.g > 5 && cleared.b > 5, `cleared background should use renderer default color (${cleared.g}, ${cleared.b})`)

  const textureScene = new THREE.Scene()
  textureScene.background = solidTexture(0, 255, 0)
  const textureBackground = meanRgba(renderRgba(textureScene, camera, { width: 64, height: 64 }))
  textureScene.backgroundIntensity = 'ignored'
  textureScene.backgroundBlurriness = 'ignored'
  const textureCleared = meanRgba(renderRgba(textureScene, camera, { width: 64, height: 64, background: null }))

  assert.ok(textureBackground.g > 180, `scene texture background should render green (${textureBackground.g})`)
  assert.ok(
    textureCleared.g < textureBackground.g - 120,
    `options.background null should clear scene texture background (${textureCleared.g} vs ${textureBackground.g})`,
  )
})

test('Renderer clear color state applies as background fallback', () => {
  const scene = new THREE.Scene()
  const camera = makeCamera()
  const renderer = new Renderer()

  renderer.setClearColor(0x204080, 0.5)
  assert.equal(renderer.getClearAlpha(), 0.5)

  const clearColor = renderer.getClearColor()
  assert.ok(Math.abs(clearColor.r - 0x20 / 255) < 1e-6, `clear red should match hex input (${clearColor.r})`)
  assert.ok(Math.abs(clearColor.g - 0x40 / 255) < 1e-6, `clear green should match hex input (${clearColor.g})`)
  assert.ok(Math.abs(clearColor.b - 0x80 / 255) < 1e-6, `clear blue should match hex input (${clearColor.b})`)

  const colorTarget = new THREE.Color()
  assert.strictEqual(renderer.getClearColor(colorTarget), colorTarget)
  assert.ok(Math.abs(colorTarget.r - 0x20 / 255) < 1e-6, `target clear red should match hex input (${colorTarget.r})`)
  assert.ok(Math.abs(colorTarget.g - 0x40 / 255) < 1e-6, `target clear green should match hex input (${colorTarget.g})`)
  assert.ok(Math.abs(colorTarget.b - 0x80 / 255) < 1e-6, `target clear blue should match hex input (${colorTarget.b})`)

  const clear = meanRgba(renderer.render(scene, camera, { width: 32, height: 32, format: 'rgba' }))
  assertRgbClose(clear, [0x20, 0x40, 0x80], 'Renderer clear color fallback')
  assert.ok(Math.abs(clear.a - 128) <= 1, `Renderer clear alpha fallback should be half opacity (${clear.a})`)

  renderer.setClearColor('rgb(32, 64, 128)', 0.5)
  const cssClearColor = renderer.getClearColor()
  assert.ok(Math.abs(cssClearColor.r - 0x20 / 255) < 1e-3, `CSS clear red should match rgb() input (${cssClearColor.r})`)
  assert.ok(Math.abs(cssClearColor.g - 0x40 / 255) < 1e-3, `CSS clear green should match rgb() input (${cssClearColor.g})`)
  assert.ok(Math.abs(cssClearColor.b - 0x80 / 255) < 1e-3, `CSS clear blue should match rgb() input (${cssClearColor.b})`)
  const cssClear = meanRgba(renderer.render(scene, camera, { width: 32, height: 32, format: 'rgba' }))
  assertRgbClose(cssClear, [0x20, 0x40, 0x80], 'Renderer CSS clear color fallback')
  assert.ok(Math.abs(cssClear.a - 128) <= 1, `Renderer CSS clear alpha fallback should be half opacity (${cssClear.a})`)

  const originalColorManagementEnabled = THREE.ColorManagement.enabled
  try {
    THREE.ColorManagement.enabled = false
    renderer.setClearColor('rgb(32, 64, 128)', 0.5)
    const disabledManagementClearColor = renderer.getClearColor()
    assert.ok(
      Math.abs(disabledManagementClearColor.r - 0x20 / 255) < 1e-3,
      `CSS clear red should ignore external ColorManagement state (${disabledManagementClearColor.r})`,
    )
  } finally {
    THREE.ColorManagement.enabled = originalColorManagementEnabled
  }

  scene.background = new THREE.Color(1, 0, 0)
  const sceneBackground = meanRgba(renderer.render(scene, camera, { width: 32, height: 32, format: 'rgba' }))
  assertRgbClose(sceneBackground, [255, 0, 0], 'scene background should override Renderer clear color')
  assert.ok(Math.abs(sceneBackground.a - 255) <= 1, `scene background alpha should remain opaque (${sceneBackground.a})`)

  renderer.setClearAlpha(0.25)
  const cleared = meanRgba(renderer.render(scene, camera, { width: 32, height: 32, format: 'rgba', background: null }))
  assertRgbClose(cleared, [0x20, 0x40, 0x80], 'options.background null should use Renderer clear color')
  assert.ok(Math.abs(cleared.a - 64) <= 1, `setClearAlpha should update fallback alpha (${cleared.a})`)

  const optionBackground = meanRgba(renderer.render(scene, camera, {
    width: 32,
    height: 32,
    format: 'rgba',
    background: [0, 1, 0, 0.75],
  }))
  assertRgbClose(optionBackground, [0, 255, 0], 'options.background color should override Renderer clear color')
  assert.ok(Math.abs(optionBackground.a - 191) <= 1, `options.background alpha should override Renderer clear alpha (${optionBackground.a})`)
})

test('Renderer constructor validates WebGLRenderer-compatible parameters', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 1)
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(4, 4),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  ))
  const camera = makeCamera()

  const renderer = new Renderer({
    alpha: true,
    depth: true,
    stencil: false,
    antialias: true,
    premultipliedAlpha: false,
    preserveDrawingBuffer: true,
    powerPreference: 'high-performance',
    failIfMajorPerformanceCaveat: false,
    samples: 0,
    outputBufferType: THREE.UnsignedByteType,
    logarithmicDepthBuffer: false,
    reversedDepthBuffer: false,
  })
  assert.equal(renderer.reversedDepthBuffer, false)
  assert.equal(renderer.getOutputBufferType(), THREE.UnsignedByteType)
  assert.equal(renderer.getColorBufferType(), THREE.UnsignedByteType)
  assert.deepEqual(renderer.getContextAttributes(), {
    alpha: true,
    depth: true,
    stencil: false,
    antialias: true,
    premultipliedAlpha: false,
    preserveDrawingBuffer: true,
    powerPreference: 'high-performance',
    failIfMajorPerformanceCaveat: false,
  })
  assert.equal(renderer.alpha, true)
  assert.equal(renderer.depth, true)
  assert.equal(renderer.stencil, false)
  assert.equal(renderer.logarithmicDepthBuffer, false)
  const mutableAttributes = renderer.getContextAttributes()
  mutableAttributes.alpha = false
  assert.equal(renderer.getContextAttributes().alpha, true)

  assert.deepEqual(new Renderer().getContextAttributes(), {
    alpha: false,
    depth: true,
    stencil: false,
    antialias: false,
    premultipliedAlpha: true,
    preserveDrawingBuffer: false,
    powerPreference: 'default',
    failIfMajorPerformanceCaveat: false,
  })
  assert.throws(
    () => renderer.getContext(),
    /Renderer\.getContext\(\) is not supported/i,
  )

  const rgba = renderer.render(scene, camera, { width: 32, height: 32, format: 'rgba' })
  const mean = meanRegion(rgba, 32, 32, 10, 10, 22, 22)
  assert.ok(mean.r > mean.b + 80, `constructor compatibility parameters should preserve normal rendering (${mean.r} vs ${mean.b})`)

  assert.throws(
    () => new Renderer(null),
    /Renderer parameters must be an object when provided/i,
  )
  assert.throws(
    () => new Renderer({ antialias: 'yes' }),
    /Renderer parameters\.antialias must be a boolean/i,
  )
  assert.throws(
    () => new Renderer({ powerPreference: 'maximum-performance' }),
    /Renderer parameters\.powerPreference "maximum-performance" is not supported/i,
  )
  assert.throws(
    () => new Renderer({ outputBufferType: 'HalfFloatType' }),
    /Renderer parameters\.outputBufferType must be a Three\.js texture type integer/i,
  )
  assert.throws(
    () => new Renderer({ outputBufferType: THREE.HalfFloatType }),
    /Renderer parameters\.outputBufferType .*not supported.*Omit outputBufferType.*FloatType or HalfFloatType/i,
  )
  assert.throws(
    () => new Renderer({ samples: '4' }),
    /Renderer parameters\.samples must be a non-negative integer sample count/i,
  )
  assert.throws(
    () => new Renderer({ samples: 4 }),
    /Renderer parameters\.samples 4 is not supported as constructor-level MSAA state.*render options samples\/sampleCount/i,
  )
  assert.throws(
    () => new Renderer({ canvas: {} }),
    /Renderer parameters\.canvas is not supported/i,
  )
  assert.throws(
    () => new Renderer({ context: {} }),
    /Renderer parameters\.context is not supported/i,
  )
  assert.throws(
    () => new Renderer({ logarithmicDepthBuffer: true }),
    /Renderer parameters\.logarithmicDepthBuffer true is not supported/i,
  )
  assert.throws(
    () => new Renderer({ reversedDepthBuffer: true }),
    /Renderer parameters\.reversedDepthBuffer true is not supported/i,
  )
  assert.throws(
    () => new Renderer({ reverseDepthBuffer: true }),
    /Renderer parameters\.reverseDepthBuffer true is not supported/i,
  )
})

test('Renderer transmissionResolutionScale is validated compatibility state', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 1)
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(4, 4),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  ))
  const camera = makeCamera()
  const renderer = new Renderer()

  assert.equal(renderer.transmissionResolutionScale, 1)
  renderer.transmissionResolutionScale = 0.5
  assert.equal(renderer.transmissionResolutionScale, 0.5)
  renderer.transmissionResolutionScale = 2
  assert.equal(renderer.transmissionResolutionScale, 2)

  const rgba = renderer.render(scene, camera, { width: 32, height: 32, format: 'rgba' })
  const mean = meanRegion(rgba, 32, 32, 10, 10, 22, 22)
  assert.ok(mean.r > mean.b + 80, `transmissionResolutionScale state should not alter normal rendering (${mean.r} vs ${mean.b})`)

  assert.throws(
    () => { renderer.transmissionResolutionScale = 0 },
    /Renderer\.transmissionResolutionScale must be greater than 0/i,
  )
  assert.throws(
    () => { renderer.transmissionResolutionScale = Number.NaN },
    /Renderer\.transmissionResolutionScale must be a finite number/i,
  )
  assert.throws(
    () => { renderer.transmissionResolutionScale = 'half' },
    /Renderer\.transmissionResolutionScale must be a finite number/i,
  )
  assert.throws(
    () => renderer.render(scene, camera, { width: 32, height: 32, transmissionResolutionScale: 0 }),
    /options\.transmissionResolutionScale must be greater than 0/i,
  )
  assert.throws(
    () => renderer.render(scene, camera, { width: 32, height: 32, transmissionResolutionScale: Number.NaN }),
    /options\.transmissionResolutionScale must be a finite number/i,
  )
  assert.throws(
    () => renderer.render(scene, camera, { width: 32, height: 32, transmissionResolutionScale: 'half' }),
    /options\.transmissionResolutionScale must be a finite number/i,
  )
})

test('Renderer domElement is an inert output-size mirror', () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 1)
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(4, 4),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  ))
  const camera = makeCamera()
  const renderer = new Renderer()

  assert.equal(renderer.domElement.width, 0)
  assert.equal(renderer.domElement.height, 0)
  assert.equal(renderer.domElement.clientWidth, 0)
  assert.equal(renderer.domElement.clientHeight, 0)
  assert.equal(renderer.domElement.offsetWidth, 0)
  assert.equal(renderer.domElement.offsetHeight, 0)
  assert.deepEqual(renderer.domElement.getBoundingClientRect(), {
    x: 0,
    y: 0,
    width: 0,
    height: 0,
    top: 0,
    right: 0,
    bottom: 0,
    left: 0,
  })
  assert.deepEqual(renderer.domElement.style, { width: '0px', height: '0px' })
  assert.throws(
    () => renderer.domElement.getContext('webgl'),
    /Renderer\.domElement\.getContext\(\) is not supported.*inert offscreen compatibility object/i,
  )
  assert.throws(
    () => renderer.domElement.toDataURL('image/png'),
    /Renderer\.domElement\.toDataURL\(\) is not supported.*Renderer\.render\(\).*PNG Buffer/i,
  )
  assert.throws(
    () => renderer.domElement.toBlob(() => {}, 'image/png'),
    /Renderer\.domElement\.toBlob\(\) is not supported.*Renderer\.render\(\).*PNG Buffer/i,
  )
  assert.throws(
    () => renderer.domElement.toBlob(null),
    /Renderer\.domElement\.toBlob callback must be a function/i,
  )
  assert.throws(
    () => renderer.domElement.captureStream(),
    /Renderer\.domElement\.captureStream\(\) is not supported.*inert offscreen compatibility object/i,
  )
  assert.throws(
    () => renderer.domElement.transferToImageBitmap(),
    /Renderer\.domElement\.transferToImageBitmap\(\) is not supported.*not an OffscreenCanvas/i,
  )

  renderer.setSize(64, 32)
  assert.equal(renderer.domElement.width, 64)
  assert.equal(renderer.domElement.height, 32)
  assert.equal(renderer.domElement.clientWidth, 64)
  assert.equal(renderer.domElement.clientHeight, 32)
  assert.equal(renderer.domElement.offsetWidth, 64)
  assert.equal(renderer.domElement.offsetHeight, 32)
  assert.deepEqual(renderer.domElement.getBoundingClientRect(), {
    x: 0,
    y: 0,
    width: 64,
    height: 32,
    top: 0,
    right: 64,
    bottom: 32,
    left: 0,
  })
  assert.deepEqual(renderer.domElement.style, { width: '64px', height: '32px' })

  renderer.setSize(48, 24, false)
  assert.equal(renderer.domElement.width, 48)
  assert.equal(renderer.domElement.height, 24)
  assert.equal(renderer.domElement.clientWidth, 64)
  assert.equal(renderer.domElement.clientHeight, 32)
  assert.deepEqual(renderer.domElement.style, { width: '64px', height: '32px' })

  renderer.setDrawingBufferSize(40, 20, 2)
  assert.equal(renderer.domElement.width, 40)
  assert.equal(renderer.domElement.height, 20)
  assert.equal(renderer.domElement.clientWidth, 40)
  assert.equal(renderer.domElement.clientHeight, 20)
  assert.deepEqual(renderer.domElement.style, { width: '40px', height: '20px' })
  assert.equal(renderer.getPixelRatio(), 2)
  renderer.domElement.style.width = '12.5px'
  renderer.domElement.style.height = 'invalid'
  assert.equal(renderer.domElement.clientWidth, 13)
  assert.equal(renderer.domElement.clientHeight, 20)
  assert.equal(renderer.domElement.offsetWidth, 13)
  assert.equal(renderer.domElement.offsetHeight, 20)
  renderer.domElement.style.width = '40px'
  renderer.domElement.style.height = '20px'
  assert.equal(renderer.domElement.style.getPropertyValue('width'), '40px')
  renderer.domElement.style.setProperty('width', '12.5px')
  assert.equal(renderer.domElement.clientWidth, 13)
  assert.equal(renderer.domElement.style.removeProperty('width'), '12.5px')
  assert.equal(renderer.domElement.clientWidth, 40)
  renderer.domElement.style.setProperty('width', '40px')
  renderer.domElement.style.setProperty('touch-action', 'none')
  assert.equal(renderer.domElement.style.touchAction, 'none')
  assert.equal(renderer.domElement.style.getPropertyValue('touch-action'), 'none')
  assert.equal(renderer.domElement.style.removeProperty('touch-action'), 'none')
  assert.equal(renderer.domElement.style.getPropertyValue('touch-action'), '')
  renderer.domElement.style.setProperty('--renderer-mode', 'headless')
  assert.equal(renderer.domElement.style.getPropertyValue('--renderer-mode'), 'headless')
  assert.equal(renderer.domElement.style.removeProperty('--renderer-mode'), 'headless')
  assert.deepEqual(renderer.domElement.style, { width: '40px', height: '20px' })

  assert.equal(renderer.domElement.getAttribute('data-renderer'), null)
  assert.equal(renderer.domElement.hasAttribute('data-renderer'), false)
  renderer.domElement.setAttribute('data-renderer', 'headless')
  renderer.domElement.setAttribute('data-count', 3)
  assert.equal(renderer.domElement.getAttribute('data-renderer'), 'headless')
  assert.equal(renderer.domElement.getAttribute('data-count'), '3')
  assert.equal(renderer.domElement.hasAttribute('data-renderer'), true)
  renderer.domElement.removeAttribute('data-renderer')
  assert.equal(renderer.domElement.getAttribute('data-renderer'), null)
  assert.equal(renderer.domElement.hasAttribute('data-renderer'), false)
  assert.throws(
    () => renderer.domElement.setAttribute('', 'value'),
    /Renderer\.domElement\.setAttribute name must be a non-empty string/i,
  )
  assert.throws(
    () => renderer.domElement.getAttribute(null),
    /Renderer\.domElement\.getAttribute name must be a non-empty string/i,
  )
  assert.throws(
    () => renderer.domElement.style.setProperty('', 'none'),
    /Renderer\.domElement\.style\.setProperty propertyName must be a non-empty string/i,
  )
  assert.throws(
    () => renderer.domElement.style.getPropertyValue(null),
    /Renderer\.domElement\.style\.getPropertyValue propertyName must be a non-empty string/i,
  )
  assert.throws(
    () => renderer.domElement.style.removeProperty('set-property'),
    /Renderer\.domElement\.style\.removeProperty propertyName must not name a reserved style method/i,
  )

  const eventCalls = []
  function onContextLost(event) {
    eventCalls.push([event.type, this === renderer.domElement])
  }
  renderer.domElement.addEventListener('webglcontextlost', onContextLost)
  assert.equal(renderer.domElement.dispatchEvent({ type: 'webglcontextlost' }), true)
  renderer.domElement.removeEventListener('webglcontextlost', onContextLost)
  assert.equal(renderer.domElement.dispatchEvent({ type: 'webglcontextlost' }), true)
  assert.deepEqual(eventCalls, [['webglcontextlost', true]])
  assert.throws(
    () => renderer.domElement.addEventListener('', onContextLost),
    /Renderer\.domElement\.addEventListener type must be a non-empty string/i,
  )
  assert.throws(
    () => renderer.domElement.removeEventListener('webglcontextlost', null),
    /Renderer\.domElement\.removeEventListener listener must be a function/i,
  )
  assert.throws(
    () => renderer.domElement.dispatchEvent({ type: '' }),
    /Renderer\.domElement\.dispatchEvent event\.type must be a non-empty string/i,
  )
  assert.throws(
    () => renderer.domElement.dispatchEvent(null),
    /Renderer\.domElement\.dispatchEvent event must be an event-like object/i,
  )

  const rgba = renderer.render(scene, camera, { format: 'rgba' })
  assert.equal(rgba.length, 40 * 20 * 4)
  const mean = meanRegion(rgba, 40, 20, 12, 6, 28, 14)
  assert.ok(mean.r > mean.b + 80, `domElement size mirroring should preserve normal rendering (${mean.r} vs ${mean.b})`)
})

test('Renderer.backend tracks the installed CommonRenderer Backend method surface', () => {
  const renderer = new Renderer()
  const backendMethods = extractCommonBackendMethodNames()
  assert.ok(backendMethods.size > 40, 'Expected to find installed Three.js CommonRenderer Backend methods.')

  const missingBackendMethods = [...backendMethods]
    .filter((methodName) => !objectSurfaceNames(renderer.backend).has(methodName))
    .sort()
  assert.deepEqual(
    missingBackendMethods,
    [],
    `Renderer.backend is missing installed Three.js CommonRenderer Backend methods: ${missingBackendMethods.join(', ')}`,
  )
})

test('Renderer.state tracks the installed WebGLState method surface', () => {
  const renderer = new Renderer()
  const webGlStateMethods = extractWebGlStateMethodNames()
  assert.ok(webGlStateMethods.size > 20, 'Expected to find installed Three.js WebGLState methods.')

  const missingStateMethods = [...webGlStateMethods]
    .filter((methodName) => !objectSurfaceNames(renderer.state).has(methodName))
    .sort()
  assert.deepEqual(missingStateMethods, [], `Renderer.state is missing installed Three.js WebGLState methods: ${missingStateMethods.join(', ')}`)

  for (const [label, functionName, stateBuffer] of [
    ['color', 'ColorBuffer', renderer.state.buffers.color],
    ['depth', 'DepthBuffer', renderer.state.buffers.depth],
    ['stencil', 'StencilBuffer', renderer.state.buffers.stencil],
  ]) {
    const webGlBufferMethods = extractWebGlStateBufferMethodNames(functionName)
    assert.ok(webGlBufferMethods.size > 3, `Expected to find installed Three.js WebGLState ${label} buffer methods.`)
    const missingBufferMethods = [...webGlBufferMethods]
      .filter((methodName) => !objectSurfaceNames(stateBuffer).has(methodName))
      .sort()
    assert.deepEqual(
      missingBufferMethods,
      [],
      `Renderer.state.buffers.${label} is missing installed Three.js WebGLState ${label} buffer methods: ${missingBufferMethods.join(', ')}`,
    )
  }
})

test('Renderer render lists and node registries track installed CommonRenderer surfaces', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  const camera = makeCamera()
  const renderList = renderer.renderLists.get(scene, camera)

  for (const [label, names, actual, minimum] of [
    ['nodes', extractJsClassSurfaceNames('src/renderers/common/nodes/Nodes.js', 'Nodes'), renderer.nodes, 20],
    ['library', extractJsClassSurfaceNames('src/renderers/common/nodes/NodeLibrary.js', 'NodeLibrary'), renderer.library, 8],
    ['lighting', extractJsClassSurfaceNames('src/renderers/common/Lighting.js', 'Lighting'), renderer.lighting, 2],
    ['renderLists', extractJsClassSurfaceNames('src/renderers/common/RenderLists.js', 'RenderLists'), renderer.renderLists, 4],
    ['renderList', extractJsClassSurfaceNames('src/renderers/common/RenderList.js', 'RenderList'), renderList, 10],
  ]) {
    assert.ok(names.size >= minimum, `Expected to find installed Three.js CommonRenderer ${label} surface names.`)
    const missing = [...names]
      .filter((name) => !objectSurfaceNames(actual).has(name))
      .sort()
    assert.deepEqual(missing, [], `Renderer ${label} is missing installed Three.js CommonRenderer ${label} names: ${missing.join(', ')}`)
  }

  assert.equal(renderer.renderLists.lists.get([scene, camera]), renderList)
  const manualScene = {}
  const manualCamera = {}
  const manualList = { id: 'manual' }
  assert.strictEqual(renderer.renderLists.lists.set([manualScene, manualCamera], manualList), renderer.renderLists.lists)
  assert.equal(renderer.renderLists.lists.get([manualScene, manualCamera]), manualList)
  assert.equal(renderer.renderLists.get(manualScene, manualCamera), manualList)
  assert.equal(renderer.renderLists.lists.delete([manualScene, manualCamera]), true)
  assert.equal(renderer.renderLists.lists.get([manualScene, manualCamera]), undefined)
  assert.equal(renderer.renderLists.lists.delete([manualScene, manualCamera]), false)
  assert.throws(
    () => renderer.renderLists.lists.get([]),
    /Renderer\.renderLists\.lists\.get keys must be a non-empty array of objects/i,
  )
  assert.throws(
    () => renderer.renderLists.lists.set([scene, null], {}),
    /Renderer\.renderLists\.lists\.set keys\[1\] must be an object/i,
  )
  assert.throws(
    () => renderer.renderLists.lists.delete('keys'),
    /Renderer\.renderLists\.lists\.delete keys must be a non-empty array of objects/i,
  )
})

