test('Renderer debug state is inert validated compatibility state', async () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 1)
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(4, 4),
    new THREE.MeshBasicMaterial({ color: 0xff0000 }),
  ))
  const camera = makeCamera()
  const renderer = new Renderer()

  assert.equal(renderer.debug.checkShaderErrors, true)
  assert.equal(renderer.debug.onShaderError, null)
  assert.equal(typeof renderer.debug.getShaderAsync, 'function')

  renderer.debug.checkShaderErrors = false
  const onShaderError = () => {}
  renderer.debug.onShaderError = onShaderError
  assert.equal(renderer.debug.checkShaderErrors, false)
  assert.equal(renderer.debug.onShaderError, onShaderError)
  renderer.debug.onShaderError = null
  assert.equal(renderer.debug.onShaderError, null)

  const rgba = renderer.render(scene, camera, { width: 32, height: 32, format: 'rgba' })
  const mean = meanRegion(rgba, 32, 32, 10, 10, 22, 22)
  assert.ok(mean.r > mean.b + 80, `debug compatibility state should not alter rendering (${mean.r} vs ${mean.b})`)

  assert.throws(
    () => { renderer.debug.checkShaderErrors = 'no' },
    /Renderer\.debug\.checkShaderErrors must be a boolean/i,
  )
  assert.throws(
    () => { renderer.debug.onShaderError = 'log' },
    /Renderer\.debug\.onShaderError must be a function or null/i,
  )
  await assert.rejects(
    () => renderer.debug.getShaderAsync(scene, camera, scene.children[0]),
    /Renderer\.debug\.getShaderAsync\(\) is not supported.*generated backend shader source is not exposed/i,
  )
  await assert.rejects(
    () => renderer.debug.getShaderAsync({}, camera, scene.children[0]),
    /THREE\.Scene or THREE\.Object3D root/i,
  )
  await assert.rejects(
    () => renderer.debug.getShaderAsync(scene, {}, scene.children[0]),
    /THREE\.Camera, THREE\.ArrayCamera, or THREE\.CubeCamera/i,
  )
  await assert.rejects(
    () => renderer.debug.getShaderAsync(scene, camera, null),
    /Renderer\.debug\.getShaderAsync object must be an object-like value/i,
  )
})

test('Renderer compile hooks return validated material sets', async () => {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 1)
  const material = new THREE.MeshBasicMaterial({ color: 0xff0000 })
  const arrayMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff00 })
  scene.add(new THREE.Mesh(
    new THREE.PlaneGeometry(4, 4),
    material,
  ))
  scene.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-1, -1, 0), new THREE.Vector3(1, 1, 0)]),
    [material, arrayMaterial],
  ))
  const targetScene = new THREE.Scene()
  const camera = makeCamera()
  const renderer = new Renderer()

  const compiledMaterials = renderer.compile(scene, camera)
  assert.ok(compiledMaterials instanceof Set)
  assert.equal(compiledMaterials.size, 2)
  assert.equal(compiledMaterials.has(material), true)
  assert.equal(compiledMaterials.has(arrayMaterial), true)

  const asyncCompiledMaterials = await renderer.compileAsync(scene, camera)
  assert.ok(asyncCompiledMaterials instanceof Set)
  assert.equal(asyncCompiledMaterials.size, 2)
  assert.equal(asyncCompiledMaterials.has(material), true)

  const targetCompiledMaterials = await renderer.compileAsync(scene, camera, targetScene)
  assert.ok(targetCompiledMaterials instanceof Set)
  assert.equal(targetCompiledMaterials.size, 2)

  const rgba = renderer.render(scene, camera, { width: 32, height: 32, format: 'rgba' })
  const mean = meanRegion(rgba, 32, 32, 10, 10, 22, 22)
  assert.ok(mean.r > mean.b + 80, `compile hooks should not alter later rendering (${mean.r} vs ${mean.b})`)

  assert.throws(
    () => renderer.compile({}, camera),
    /THREE\.Scene or THREE\.Object3D root/i,
  )
  await assert.rejects(
    () => renderer.compileAsync(scene, {}),
    /THREE\.Camera, THREE\.ArrayCamera, or THREE\.CubeCamera/i,
  )
  await assert.rejects(
    () => renderer.compileAsync(scene, camera, {}),
    /THREE\.Scene or THREE\.Object3D root/i,
  )
  assert.throws(
    () => renderer.compile(Object.assign(new THREE.Object3D(), {
      isMesh: true,
      material: ['invalid'],
    }), camera),
    /Renderer\.compile scene\.material\[0\] must be a material-like object/i,
  )
})

test('Renderer invokes WebGLRenderer-style object render callbacks', () => {
  const renderer = new Renderer()
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0, 0, 0)
  const camera = makeCamera()
  const geometry = new THREE.PlaneGeometry(4, 4)
  const material = new THREE.MeshBasicMaterial({ color: 0xff0000 })
  const mesh = new THREE.Mesh(geometry, material)
  scene.add(mesh)

  let beforeCalls = 0
  let afterCalls = 0
  mesh.onBeforeRender = function (rendererArg, sceneArg, cameraArg, geometryArg, materialArg, groupArg) {
    beforeCalls += 1
    assert.equal(this, mesh)
    assert.equal(rendererArg, renderer)
    assert.equal(sceneArg, scene)
    assert.equal(cameraArg, camera)
    assert.equal(geometryArg, geometry)
    assert.equal(materialArg, material)
    assert.equal(groupArg.start, 0)
    materialArg.color.set(0x00ff00)
  }
  mesh.onAfterRender = function (rendererArg, sceneArg, cameraArg, geometryArg, materialArg, groupArg) {
    afterCalls += 1
    assert.equal(this, mesh)
    assert.equal(rendererArg, renderer)
    assert.equal(sceneArg, scene)
    assert.equal(cameraArg, camera)
    assert.equal(geometryArg, geometry)
    assert.equal(materialArg, material)
    assert.equal(groupArg.count, 6)
    materialArg.color.set(0xff0000)
  }

  const rgba = renderer.render(scene, camera, {
    width: 32,
    height: 32,
    format: 'rgba',
    outputColorSpace: THREE.LinearSRGBColorSpace,
  })
  const mean = meanRegion(rgba, 32, 32, 10, 10, 22, 22)
  assert.equal(beforeCalls, 1)
  assert.equal(afterCalls, 1)
  assert.ok(mean.g > mean.r + 80, `onBeforeRender material mutation should affect queued draw (${mean.r}, ${mean.g}, ${mean.b})`)
  assert.equal(material.color.getHex(), 0xff0000, 'onAfterRender should be able to restore material state after extraction')

  mesh.onBeforeRender = 'callback'
  assert.throws(
    () => renderer.render(scene, camera, { width: 16, height: 16, format: 'rgba' }),
    /THREE\.Object3D\.onBeforeRender must be a function when provided/i,
  )
})

